// Data grammar-n3 — dihasilkan otomatis (lihat scripts/fetch-data.mjs).
export default [{"pattern":"A その上 B","meaning":"Used to express 'in addition to', 'besides', or 'furthermore' when adding information or making a suggestion.","formation":"A [sentence/clause] + その上 + B [sentence/clause]","examples":[{"jp":"彼は頭が良い。その上、スポーツも得意だ。","en":"He is smart. In addition, he is also good at sports.","romaji":"Kare wa atama ga ii. Sono ue, supootsu mo tokui da."},{"jp":"このカフェは雰囲気がいい。その上、料理も美味しい。","en":"This cafe has a nice atmosphere. Besides, the food is delicious.","romaji":"Kono kafe wa fun'iki ga ii. Sono ue, ryouri mo oishii."},{"jp":"このアパートは駅に近い。その上、家賃も安い。","en":"This apartment is close to the station. Furthermore, the rent is also cheap.","romaji":"Kono apaato wa eki ni chikai. Sono ue, yachin mo yasui."},{"jp":"彼女は仕事ができる。その上、誰とでも仲良くなれる。","en":"She is competent at work. In addition, she can get along with anyone.","romaji":"Kanojo wa shigoto ga dekiru. Sono ue, dare to demo nakayoku nareru."}],"example":"彼は頭が良い。その上、スポーツも得意だ。","exampleMeaning":"He is smart. In addition, he is also good at sports."},{"pattern":"～うちに (〜uchi ni)","meaning":"Express 'while', 'before', or 'during' a certain condition or situation.","formation":"Verb-てform + いる + うちに, い-Adjective + い + うちに, な-Adjective + な + うちに","examples":[{"jp":"若いうちに、いろいろな経験をしておくことが大切です。","en":"It is important to have various experiences while you are young.","romaji":"Wakai uchi ni, iroiro na keiken wo shite oku koto ga taisetsu desu."},{"jp":"雨が降っていないうちに、買い物に行こう。","en":"Let's go shopping before it starts raining.","romaji":"Ame ga futte inai uchi ni, kaimono ni ikou."},{"jp":"料理が熱いうちに食べましょう。","en":"Let's eat while the food is still hot.","romaji":"Ryouri ga atsui uchi ni tabemashou."},{"jp":"休みのうちに、旅行の計画を立てたいです。","en":"I want to plan a trip during the holidays.","romaji":"Yasumi no uchi ni, ryokou no keikaku wo tatetai desu."}],"example":"若いうちに、いろいろな経験をしておくことが大切です。","exampleMeaning":"It is important to have various experiences while you are young."},{"pattern":"～うとした (〜uto shita)","meaning":"Express an action someone tried to do but couldn't; 'tried to', 'attempted to'.","formation":"Verb-う stem + とした","examples":[{"jp":"電話に出ようとしたが、相手は切ってしまった。","en":"I tried to answer the phone, but the other person hung up.","romaji":"Denwa ni deyou to shita ga, aite wa kitte shimatta."},{"jp":"彼は大声で話そうとしたが、言葉が出なかった。","en":"He tried to speak loudly, but no words came out.","romaji":"Kare wa oogoe de hanasou to shita ga, kotoba ga denakatta."},{"jp":"ケーキを作ろうとしたが、材料が足りなかった。","en":"I tried to make a cake, but I didn't have enough ingredients.","romaji":"Keeki wo tsukurou to shita ga, zairyou ga tarinakatta."},{"jp":"彼女は泳ごうとしたが、怖くて水に入れなかった。","en":"She tried to swim, but she was scared and couldn't get in the water.","romaji":"Kanojo wa oyogou to shita ga, kowakute mizu ni irenakatta."}],"example":"電話に出ようとしたが、相手は切ってしまった。","exampleMeaning":"I tried to answer the phone, but the other person hung up."},{"pattern":"～おかげで (〜okagede)","meaning":"Expresses gratitude or shows a positive result due to a certain factor; 'thanks to', 'because of'.","formation":"Verb-casual + おかげで, い-Adjective + おかげで, な-Adjective + だおかげで, Noun + のおかげで","examples":[{"jp":"お母さんのおかげで、私は元気になりました。","en":"Thanks to my mother, I became healthy.","romaji":"Okaasan no okagede, watashi wa genki ni narimashita."},{"jp":"先生の助けのおかげで、試験に合格しました。","en":"Thanks to the teacher's help, I passed the exam.","romaji":"Sensei no tasuke no okagede, shiken ni goukaku shimashita."},{"jp":"日本語の勉強のおかげで、この映画が理解できました。","en":"Thanks to studying Japanese, I was able to understand this movie.","romaji":"Nihongo no benkyou no okagede, kono eiga ga rikai dekimashita."},{"jp":"晴れた天気のおかげで、ピクニックが楽しかったです。","en":"Thanks to the sunny weather, the picnic was enjoyable.","romaji":"Hareta tenki no okagede, pikunikku ga tanoshikatta desu."}],"example":"お母さんのおかげで、私は元気になりました。","exampleMeaning":"Thanks to my mother, I became healthy."},{"pattern":"～かけ (〜kake)","meaning":"Expresses the meaning of being in the middle of doing something or of something being partway done.","formation":"Verb-ますstem + かけ","examples":[{"jp":"彼は食事を食べかけです。","en":"He is in the middle of eating his meal.","romaji":"Kare wa shokuji wo tabekake desu."},{"jp":"この本は読みかけで、まだ終わっていません。","en":"This book is partway read, and it is not yet finished.","romaji":"Kono hon wa yomikake de, mada owatteimasen."},{"jp":"この部屋は掃除しかけで、まだ片づいていません。","en":"This room is partway cleaned, and it's not yet tidied up.","romaji":"Kono heya wa soujishikake de, mada kataduiteimasen."},{"jp":"プロジェクトは進行しかけで、来週には完了する予定です。","en":"The project is in progress and is scheduled to be completed next week.","romaji":"Purojekuto wa shinkoushikake de, raishuu ni wa kanryou suru yotei desu."}],"example":"彼は食事を食べかけです。","exampleMeaning":"He is in the middle of eating his meal."},{"pattern":"～かなあ (〜kanaa)","meaning":"Expressing uncertainty or a mild wish; 'I wonder', 'maybe'.","formation":"Verb-casual + かなあ, い-Adjective + かなあ, な-Adjective + だかなあ, Noun + だかなあ","examples":[{"jp":"明日晴れるかなあ。","en":"I wonder if it will be sunny tomorrow.","romaji":"Ashita hareru kanaa."},{"jp":"このスープ、辛いかなあ。","en":"I wonder if this soup is spicy.","romaji":"Kono suupu, karai kanaa."},{"jp":"彼は静かだかなあ。","en":"I wonder if he is quiet.","romaji":"Kare wa shizuka da kanaa."},{"jp":"彼女は医者だかなあ。","en":"I wonder if she is a doctor.","romaji":"Kanojo wa isha da kanaa."}],"example":"明日晴れるかなあ。","exampleMeaning":"I wonder if it will be sunny tomorrow."},{"pattern":"～ないで (〜naide)","meaning":"Express 'without doing ~' or 'without ~ing'.","formation":"Verb-ない-form + で","examples":[{"jp":"会わないでその電話をかけました。","en":"I made the phone call without meeting them.","romaji":"Awanai de sono denwa wo kakemashita."},{"jp":"雨が降るのを待たないで、家を出ました。","en":"I left the house without waiting for it to rain.","romaji":"Ame ga furu no wo matanai de, ie wo demashita."},{"jp":"誰にも聞かないで、その秘密を知りました。","en":"I found out the secret without asking anyone.","romaji":"Dare ni mo kikanai de, sono himitsu wo shirimashita."},{"jp":"遅れることを知らないで、駅に向かいました。","en":"I headed to the station without knowing I was late.","romaji":"Okureru koto wo shiranai de, eki ni mukaimashita."}],"example":"会わないでその電話をかけました。","exampleMeaning":"I made the phone call without meeting them."},{"pattern":"～から～にかけて (〜kara 〜ni kakete)","meaning":"Expresses a range of something, such as time or space; 'from...to', 'between'.","formation":"Noun (time, place, or measure) + から + Noun (time, place or measure) + にかけて","examples":[{"jp":"午前８時から午後５時にかけて働いています。","en":"I work from 8 am to 5 pm.","romaji":"Gozen hachiji kara gogo goji ni kakete hataraiteru."},{"jp":"この地域は、北から南にかけて狭いです。","en":"This area is narrow from north to south.","romaji":"Kono chiiki wa, kita kara minami ni kakete semai desu."},{"jp":"１０歳から２０歳にかけて成長が早いです。","en":"Growth is rapid from 10 to 20 years of age.","romaji":"Jussai kara nijussai ni kakete seichou ga hayai desu."},{"jp":"今年の夏は、６月から８月にかけて雨が多かった。","en":"This summer, there was a lot of rain from June to August.","romaji":"Kotoshi no natsu wa, roku gatsu kara hachi gatsu ni kakete ame ga ookatta."}],"example":"午前８時から午後５時にかけて働いています。","exampleMeaning":"I work from 8 am to 5 pm."},{"pattern":"～かわりに (〜kawari ni)","meaning":"In place of; instead of; as a substitute for.","formation":"Verb-casual + かわりに, い-Adjective + かわりに, な-Adjective + だかわりに, Noun + だかわりに","examples":[{"jp":"映画を見るかわりに、本を読んだ。","en":"Instead of watching a movie, I read a book.","romaji":"Eiga wo miru kawari ni, hon wo yonda."},{"jp":"お酒を飲むかわりに、水を飲んでください。","en":"Please drink water instead of alcohol.","romaji":"Osake wo nomu kawari ni, mizu wo nonde kudasai."},{"jp":"犬のかわりに、猫を飼いたいです。","en":"I want to keep a cat instead of a dog.","romaji":"Inu no kawari ni, neko wo kaitai desu."},{"jp":"電車を使わないかわりに、自転車で行くことにしました。","en":"I decided to go by bicycle instead of using the train.","romaji":"Densha wo tsukawanai kawari ni, jitensha de iku koto ni shimashita."}],"example":"映画を見るかわりに、本を読んだ。","exampleMeaning":"Instead of watching a movie, I read a book."},{"pattern":"～きり (〜kiri)","meaning":"Expresses the idea of 'only', 'since', or 'after'.","formation":"Verb-past + きり, Verb-てform + きり (less common), Noun + きり","examples":[{"jp":"彼は出かけたきり帰ってきません。","en":"He went out and hasn't come back since.","romaji":"Kare wa dekaketa kiri kaette kimasen."},{"jp":"昨日コーヒーを飲んだきり、何も飲まなかった。","en":"I haven't had anything to drink since the coffee I had yesterday.","romaji":"Kinou koohii wo nonda kiri, nani mo nomanakatta."},{"jp":"卒業したきり、彼女に会っていません。","en":"I haven't seen her since we graduated.","romaji":"Sotsugyou shita kiri, kanojo ni atte imasen."},{"jp":"その映画を見たきり、もう一度見たいと思っています。","en":"I've wanted to watch that movie again ever since I saw it.","romaji":"Sono eiga wo mita kiri, mou ichido mitai to omotteimasu."}],"example":"彼は出かけたきり帰ってきません。","exampleMeaning":"He went out and hasn't come back since."},{"pattern":"～くせに (〜kuse ni)","meaning":"Used to express criticism or disapproval; 'even though', 'despite', 'in spite of'.","formation":"Verb-casual + くせに, い-Adjective + くせに, な-Adjective + な/のくせに, Noun + のくせに","examples":[{"jp":"彼はお金持ちのくせに、ケチです。","en":"Even though he's rich, he's stingy.","romaji":"Kare wa okanemochi no kuse ni, kechi desu."},{"jp":"この部屋が汚いくせに、文句を言うな。","en":"Don't complain even though this room is dirty. (criticizing)","romaji":"Kono heya ga kitanai kuse ni, monku wo iu na."},{"jp":"彼は暇なくせに、手伝ってくれません。","en":"Even though he's free, he won't help me.","romaji":"Kare wa hima na kuse ni, tetsudatte kuremasen."},{"jp":"彼女は美人なくせに、デートが続かない。","en":"Even though she's beautiful, she can't keep a date going.","romaji":"Kanojo wa bijin na kuse ni, deeto ga tsudzukanai."}],"example":"彼はお金持ちのくせに、ケチです。","exampleMeaning":"Even though he's rich, he's stingy."},{"pattern":"～くらい (〜kurai)","meaning":"Expresses an approximate quantity or degree; 'about', 'approximately', or 'to the extent of'.","formation":"Verb-casual + くらい, い-Adjective + くらい, な-Adjective + くらい, Noun + くらい","examples":[{"jp":"１０分くらい待ちましょう。","en":"Let's wait for about 10 minutes.","romaji":"Juppun kurai machimashou."},{"jp":"彼女はその映画を５回くらい見ました。","en":"She watched that movie about five times.","romaji":"Kanojo wa sono eiga wo go-kai kurai mimashita."},{"jp":"その本は面白いくらい難しいです。","en":"That book is so difficult that it’s interesting.","romaji":"Sono hon wa omoshiroi kurai muzukashii desu."},{"jp":"この部屋はきれいなくらい広いです。","en":"This room is spacious to the extent of being beautiful.","romaji":"Kono heya wa kirei na kurai hiroi desu."}],"example":"１０分くらい待ちましょう。","exampleMeaning":"Let's wait for about 10 minutes."},{"pattern":"～くらい～は～ない (〜kurai 〜wa 〜nai)","meaning":"Express the least one can do; 'at least', 'the least', 'no less than'.","formation":"Verb-casual (non-past) + くらい + は + Verb-casual (negative), Adjective (non-past) + くらい + は + Adjective (negative)","examples":[{"jp":"週に一度くらいはジムに行かないと。","en":"I have to go to the gym at least once a week.","romaji":"Shuu ni ichido kurai wa jimu ni ikanai to."},{"jp":"毎日くらいは歯を磨かないと。","en":"I have to brush my teeth at least every day.","romaji":"Mainichi kurai wa ha wo migakanai to."},{"jp":"この問題くらいは解決しないと。","en":"I have to solve at least this problem.","romaji":"Kono mondai kurai wa kaiketsu shinai to."},{"jp":"彼女が泣いているくらいなら慰めないと。","en":"If she is crying that much, I should at least try to comfort her.","romaji":"Kanojo ga naite iru kurai nara nagusamenai to."}],"example":"週に一度くらいはジムに行かないと。","exampleMeaning":"I have to go to the gym at least once a week."},{"pattern":"～こそ (〜koso)","meaning":"Emphasizes the importance or uniqueness of something or someone; 'precisely', 'exactly', 'it is...', 'of all...'.","formation":"Noun + こそ, (Verb-て + こそ)","examples":[{"jp":"今日こそ勉強しなければなりません。","en":"Today, of all days, I must study.","romaji":"Kyou koso benkyou shinakereba narimasen."},{"jp":"あなたこそ私の一番の友達です。","en":"You are precisely my best friend.","romaji":"Anata koso watashi no ichiban no tomodachi desu."},{"jp":"お金がないことこそ幸せの秘訣ではないか。","en":"Isn't not having money exactly the key to happiness?","romaji":"O-kane ga nai koto koso shiawase no hiketsu de wa nai ka."},{"jp":"彼こそまさにプロの歌手のように歌える。","en":"He can sing precisely like a professional singer.","romaji":"Kare koso masani puro no kashu no you ni utaeru."}],"example":"今日こそ勉強しなければなりません。","exampleMeaning":"Today, of all days, I must study."},{"pattern":"～こと (〜koto)","meaning":"Express an action in a nominal (noun-like) form or state fact or experience.","formation":"Verb-plain form + こと, Verb-phrase in plain form + こと","examples":[{"jp":"日本語を話すことができます。","en":"I can speak Japanese.","romaji":"Nihongo wo hanasu koto ga dekimasu."},{"jp":"毎日運動することは健康に良いです。","en":"Exercising every day is good for your health.","romaji":"Mainichi undou suru koto wa kenkou ni ii desu."},{"jp":"彼はピアノを弾くことが大好きです。","en":"He loves to play the piano.","romaji":"Kare wa piano wo hiku koto ga daisuki desu."},{"jp":"映画を見ることに時間を使いたくない。","en":"I don't want to spend time watching movies.","romaji":"Eiga wo miru koto ni jikan wo tsukai takunai."}],"example":"日本語を話すことができます。","exampleMeaning":"I can speak Japanese."},{"pattern":"～ことだ (〜koto da)","meaning":"Expresses advice or recommendation; 'should', 'it is important', 'it is necessary'.","formation":"Verb-ますstem + ことだ, い-Adjective + ことだ, な-Adjective + なことだ, Noun + のことだ","examples":[{"jp":"毎日運動することだ。","en":"You should exercise every day.","romaji":"Mainichi undou suru koto da."},{"jp":"健康のために、野菜をたくさん食べることだ。","en":"For your health, you should eat lots of vegetables.","romaji":"Kenkou no tame ni, yasai wo takusan taberu koto da."},{"jp":"勉強しているとき、静かな場所を選ぶことだ。","en":"When studying, you should choose a quiet place.","romaji":"Benkyou shiteiru toki, shizuka na basho wo erabu koto da."},{"jp":"辞書を使って、新しい言葉を覚えることだ。","en":"You should use a dictionary to learn new words.","romaji":"Jisho wo tsukatte, atarashii kotoba wo oboeru koto da."}],"example":"毎日運動することだ。","exampleMeaning":"You should exercise every day."},{"pattern":"～ことにしている (〜koto ni shite iru)","meaning":"Express a personal rule or habit; 'I make it a rule to', 'I always make sure to'.","formation":"Verb-casual + ことにしている","examples":[{"jp":"毎日運動することにしている。","en":"I make it a rule to exercise every day.","romaji":"Mainichi undou suru koto ni shite iru."},{"jp":"夜遅くまで働かないことにしている。","en":"I make it a rule not to work late into the night.","romaji":"Yoru osoku made hatarakanai koto ni shite iru."},{"jp":"食事の後、歯を磨くことにしている。","en":"I always make sure to brush my teeth after meals.","romaji":"Shokuji no ato, ha wo migaku koto ni shite iru."},{"jp":"会議には必ず10分前に着くことにしている。","en":"I always make sure to arrive 10 minutes early for meetings.","romaji":"Kaigi ni wa kanarazu juppun mae ni tsuku koto ni shite iru."}],"example":"毎日運動することにしている。","exampleMeaning":"I make it a rule to exercise every day."},{"pattern":"～ことになっている (〜koto ni natte iru)","meaning":"Describes something that is decided, arranged, or expected.","formation":"Verb-dictionary form + ことになっている","examples":[{"jp":"この会社では、20時には仕事を終えることになっている。","en":"In this company, it is decided that work will end at 8 pm.","romaji":"Kono kaisha de wa, 20-ji ni shigoto o oeru koto ni natte iru."},{"jp":"日本では、18歳以上の人が選挙に投票することになっている。","en":"In Japan, it is decided that people 18 years old and above will vote in elections.","romaji":"Nihon de wa, 18-sai ijou no hito ga senkyo ni touhyou suru koto ni natte iru."},{"jp":"学校では、制服を着ることになっている。","en":"At school, it is decided that students will wear uniforms.","romaji":"Gakkou de wa, seifuku o kiru koto ni natte iru."},{"jp":"田中さんが今回のプロジェクトリーダーになることになっている。","en":"It is decided that Tanaka will be the project leader this time.","romaji":"Tanaka-san ga konkai no purojekuto riidaa ni naru koto ni natte iru."}],"example":"この会社では、20時には仕事を終えることになっている。","exampleMeaning":"In this company, it is decided that work will end at 8 pm."},{"pattern":"～ことは…が (～koto wa... ga)","meaning":"Indicates that while something may be true or valid, there is another contrasting point.","formation":"Verb-casual + ことは + が, い-Adjective + ことは + が, な-Adjective + だ + ことは + が, Noun + だ + ことは + が","examples":[{"jp":"この映画は面白いことは面白いが、ちょっと長すぎる。","en":"This movie may be interesting, but it is a bit too long.","romaji":"Kono eiga wa omoshiroi koto wa omoshiroi ga, chotto naga-sugiru."},{"jp":"彼は親切なことは親切だが、少し無口だ。","en":"He may be kind, but he is a bit quiet.","romaji":"Kare wa shinsetsu na koto wa shinsetsu da ga, sukoshi mukuchi da."},{"jp":"このゲームは難しいことは難しいが、やめられない。","en":"This game may be difficult, but I can't stop playing.","romaji":"Kono geemu wa muzukashii koto wa muzukashii ga, yamerarenai."},{"jp":"彼女は美しいことは美しいが、ちょっと高飛車だ。","en":"She may be beautiful, but she is a bit arrogant.","romaji":"Kanojo wa utsukushii koto wa utsukushii ga, chotto koubisha da."}],"example":"この映画は面白いことは面白いが、ちょっと長すぎる。","exampleMeaning":"This movie may be interesting, but it is a bit too long."},{"pattern":"～ことはない (〜koto wa nai)","meaning":"Expresses that something doesn't need to be done or there's no occasion to do it; 'don't have to', 'not necessary'.","formation":"Verb-dictionary form + ことはない, い-Adjective + ことはない, な-Adjective + であることはない, Noun + であることはない","examples":[{"jp":"お金があるから、無理に貯金することはない。","en":"Since I have enough money, there's no need to force myself to save.","romaji":"Okane ga aru kara, muri ni chokin suru koto wa nai."},{"jp":"この本は簡単だから、辞書を使うことはない。","en":"Since this book is easy, there's no need to use a dictionary.","romaji":"Kono hon wa kantan dakara, jisho wo tsukau koto wa nai."},{"jp":"彼女は海外旅行に行きたくなければ、行くことはない。","en":"If she doesn't want to go on an overseas trip, she doesn't have to go.","romaji":"Kanojo wa kaigai ryokou ni ikitakunakereba, iku koto wa nai."},{"jp":"寒くなければ、コートを着ることはない。","en":"If it's not cold, there's no need to wear a coat.","romaji":"Samukunakereba, kooto wo kiru koto wa nai."}],"example":"お金があるから、無理に貯金することはない。","exampleMeaning":"Since I have enough money, there's no need to force myself to save."},{"pattern":"～さ (〜sa)","meaning":"Express the degree or extent of a quality; '-ness', 'degree of'.","formation":"い-Adjective (drop い) + さ, な-Adjective + さ","examples":[{"jp":"この料理は辛さが強い。","en":"The spiciness of this dish is strong.","romaji":"Kono ryouri wa karasa ga tsuyoi."},{"jp":"彼女の美しさは皆に憧れられる。","en":"Her beauty is admired by everyone.","romaji":"Kanojo no utsukushisa wa mina ni akogarerareru."},{"jp":"山田さんの親切さで、困っている人を助けてくれる。","en":"Yamada-san's kindness helps people in trouble.","romaji":"Yamada-san no shinsetsusa de, komatte iru hito wo tasukete kureru."},{"jp":"この部屋の広さは十分だと思う。","en":"I think the size of this room is enough.","romaji":"Kono heya no hirosa wa juubun da to omou."}],"example":"この料理は辛さが強い。","exampleMeaning":"The spiciness of this dish is strong."},{"pattern":"～さえ","meaning":"Emphasizes a specific item or action; 'even', 'if only', 'as long as'.","formation":"Noun + さえ, Verb-casual + さえ, い-Adjective + さえ, な-Adjective + でさえ","examples":[{"jp":"お金さえあれば、世界中を旅行できる。","en":"If only I have money, I can travel around the world.","romaji":"Okane sae areba, sekaijuu wo ryokou dekiru."},{"jp":"彼は英語さえ話せれば、その仕事ができるだろう。","en":"As long as he can speak English, he can do that job.","romaji":"Kare wa eigo sae hanasereba, sono shigoto ga dekiru darou."},{"jp":"彼女は頭がいいだけでなく、運動も上手だ。テニスさえできる。","en":"Not only is she smart, she is also good at sports. She can even play tennis.","romaji":"Kanojo wa atama ga ii dake denaku, undou mo jouzu da. Tenisu sae dekiru."},{"jp":"明るい場所で本を読むのが好きだ。部屋の電気さえつけなくても大丈夫だ。","en":"I like reading books in bright places. I'm fine even if I don't turn on the room light.","romaji":"Akarui basho de hon wo yomu no ga suki da. Heya no denki sae tsukenakute mo daijoubu da."}],"example":"お金さえあれば、世界中を旅行できる。","exampleMeaning":"If only I have money, I can travel around the world."},{"pattern":"～しかない (〜shika nai)","meaning":"Express the idea of 'only', 'no other option but', 'nothing else but'.","formation":"Verb-casual + しかない, い-Adjective + しかない, な-Adjective + しかない, Noun + しかない","examples":[{"jp":"この問題を解決する方法は一つしかない。","en":"There is only one way to solve this problem.","romaji":"Kono mondai wo kaiketsu suru houhou wa hitotsu shika nai."},{"jp":"彼が出て行ったら、泣くしかない。","en":"If he leaves, there's nothing else to do but cry.","romaji":"Kare ga dete ittara, naku shika nai."},{"jp":"彼女にはあと一月しかない。","en":"She has only one month left.","romaji":"Kanojo ni wa ato ichigatsu shika nai."},{"jp":"僕には君を信じるしかない。","en":"I have no choice but to trust you.","romaji":"Boku ni wa kimi wo shinjiru shika nai."}],"example":"この問題を解決する方法は一つしかない。","exampleMeaning":"There is only one way to solve this problem."},{"pattern":"すこしも〜ない","meaning":"Express a negative state or action; 'not at all', 'none whatsoever'.","formation":"すこしも + Verb-negative","examples":[{"jp":"彼はすこしも悲しそうに見えません。","en":"He doesn't look sad at all.","romaji":"Kare wa sukoshimo kanashisou ni miemasen."},{"jp":"この部屋はすこしも寒くない。","en":"This room is not cold at all.","romaji":"Kono heya wa sukoshimo samukunai."},{"jp":"彼女はすこしも心配していない。","en":"She is not worried at all.","romaji":"Kanojo wa sukoshimo shinpai shite inai."},{"jp":"まったく知らない人と話すのは怖い。","en":"It's scary to talk to someone I don't know at all.","romaji":"Mattaku shiranai hito to hanasu no wa kowai."}],"example":"彼はすこしも悲しそうに見えません。","exampleMeaning":"He doesn't look sad at all."},{"pattern":"～ずに (〜zu ni)","meaning":"Express 'without doing' something or 'not doing' something.","formation":"Verb-ない form (Remove ない) + ずに","examples":[{"jp":"彼は笑わずに話を聞いていました。","en":"He was listening to the story without laughing.","romaji":"Kare wa warawazu ni hanashi wo kiiteimashita."},{"jp":"食べずに寝るのは良くないです。","en":"It's not good to go to bed without eating.","romaji":"Tabezu ni neru no wa yokunai desu."},{"jp":"コーヒーを飲まずに仕事を始めました。","en":"I started working without drinking coffee.","romaji":"Koohii wo nomazu ni shigoto wo hajimemashita."},{"jp":"誰にも言わずに出かけました。","en":"I went out without telling anyone.","romaji":"Dare ni mo iwazu ni dekakemashita."}],"example":"彼は笑わずに話を聞いていました。","exampleMeaning":"He was listening to the story without laughing."},{"pattern":"～せいで (〜sei de)","meaning":"Indicates that something or someone caused an unfortunate result.","formation":"Verb-casual + せいで, い-Adjective + せいで, な-Adjective + なせいで, Noun + のせいで","examples":[{"jp":"雨のせいで試合が中止になりました。","en":"The game was cancelled because of the rain.","romaji":"Ame no sei de shiai ga chuushi ni narimashita."},{"jp":"彼の遅刻のせいで、みんな待たされました。","en":"Everyone had to wait because of his lateness.","romaji":"Kare no chikoku no sei de, minna matasaremashita."},{"jp":"病気のせいで休日が台無しになった。","en":"My holiday was ruined due to illness.","romaji":"Byouki no sei de kyuujitsu ga dainashi ni natta."},{"jp":"仕事が忙しくて寝不足なせいで、集中できない。","en":"I can't concentrate because I'm sleep-deprived due to busy work.","romaji":"Shigoto ga isogashikute nebusoku na sei de, shuuchuu dekinai."}],"example":"雨のせいで試合が中止になりました。","exampleMeaning":"The game was cancelled because of the rain."},{"pattern":"～せてください (〜sete kudasai)","meaning":"Requesting someone to allow or let you do something (causative request).","formation":"Verb-causative (させ) + て + ください","examples":[{"jp":"もう一度説明させてください。","en":"Please let me explain it once more.","romaji":"Mou ichido setsumei sasete kudasai."},{"jp":"帰らせてください。","en":"Please let me go home.","romaji":"Kaerasete kudasai."},{"jp":"その本を見せてください。","en":"Please let me see that book.","romaji":"Sono hon o misete kudasai."},{"jp":"ここで待たせてください。","en":"Please let me wait here.","romaji":"Koko de matasete kudasai."}],"example":"もう一度説明させてください。","exampleMeaning":"Please let me explain it once more."},{"pattern":"～そのために (〜sono tame ni)","meaning":"For the purpose of; because of; in order to.","formation":"Sentence/phrase 1 + そのために + Sentence/phrase 2","examples":[{"jp":"試験に合格するために、毎日勉強しています。そのために、早く寝て早く起きるようにしています。","en":"I study every day to pass the exam. For that reason, I go to bed early and wake up early.","romaji":"Shiken ni goukaku suru tame ni, mainichi benkyou shiteimasu. Sono tame ni, hayaku nete hayaku okiru you ni shiteimasu."},{"jp":"健康的な生活を送りたい。そのために、ジムに通って運動しています。","en":"I want to lead a healthy lifestyle. For that reason, I go to the gym and exercise.","romaji":"Kenkouteki na seikatsu wo okuritai. Sono tame ni, jimu ni kayotte undou shiteimasu."},{"jp":"環境を守るために、リサイクルに取り組んでいます。そのために、ゴミを分別して捨てています。","en":"I'm working on recycling to protect the environment. Therefore, I separate and dispose of trash properly.","romaji":"Kankyou wo mamoru tame ni, risaikuru ni torikundeimasu. Sono tame ni, gomi wo bunbetsu shite suteteimasu."},{"jp":"新しい仕事を見つけたい。そのために、履歴書を書いて応募しています。","en":"I want to find a new job. So, I'm writing my resume and applying.","romaji":"Atarashii shigoto wo mitsuketai. Sono tame ni, rirekisho wo kaite oubo shiteimasu."}],"example":"試験に合格するために、毎日勉強しています。そのために、早く寝て早く起きるようにしています。","exampleMeaning":"I study every day to pass the exam. For that reason, I go to bed early and wake up early."},{"pattern":"～その結果 (〜sono kekka)","meaning":"Shows the result or consequence of a previous action or situation; 'as a result', 'in consequence'.","formation":"Situation/ACTION 1 + その結果 + RESULT","examples":[{"jp":"彼女は毎日練習した。その結果、試合に勝った。","en":"She practiced every day. As a result, she won the match.","romaji":"Kanojo wa mainichi renshuu shita. Sono kekka, shiai ni katta."},{"jp":"会社が倒産した。その結果、彼は仕事を失った。","en":"The company went bankrupt. As a result, he lost his job.","romaji":"Kaisha ga tousan shita. Sono kekka, kare wa shigoto wo ushinatta."},{"jp":"私たちは遅刻した。その結果、電車に乗れなかった。","en":"We were late. As a result, we couldn't catch the train.","romaji":"Watashitachi wa chikoku shita. Sono kekka, densha ni norenakatta."},{"jp":"彼は勉強を怠った。その結果、試験に落ちた。","en":"He neglected his studies. As a result, he failed the exam.","romaji":"Kare wa benkyou wo okotatta. Sono kekka, shiken ni ochita."}],"example":"彼女は毎日練習した。その結果、試合に勝った。","exampleMeaning":"She practiced every day. As a result, she won the match."},{"pattern":"～それと～ (〜sore to〜)","meaning":"Used to link two or more items; 'and', 'also'.","formation":"Item1 + それと + Item2","examples":[{"jp":"買い物に行くつもりです。それと、郵便局にも行かなくては。","en":"I plan to go shopping, and I also have to go to the post office.","romaji":"Kaimono ni iku tsumori desu. Sore to, yuubinkyoku ni mo ikanakute wa."},{"jp":"今日はタコスを作りました。それと、サラダも作りました。","en":"Today, I made tacos, and I also made a salad.","romaji":"Kyou wa takosu wo tsukurimashita. Sore to, sarada mo tsukurimashita."},{"jp":"出かける前に、部屋を掃除してください。それと、ゴミを捨ててください。","en":"Please clean the room before you go out, and also throw away the trash.","romaji":"Dekakeru mae ni, heya wo souji shite kudasai. Sore to, gomi wo sutete kudasai."},{"jp":"彼はフランス語が話せます。それと、スペイン語も話せます。","en":"He can speak French, and he can also speak Spanish.","romaji":"Kare wa furansugo ga hanasemasu. Sore to, supeingo mo hanasemasu."}],"example":"買い物に行くつもりです。それと、郵便局にも行かなくては。","exampleMeaning":"I plan to go shopping, and I also have to go to the post office."},{"pattern":"～？それとも～？ (～? sore tomo ～?)","meaning":"Presents two alternatives or choices; 'or', 'either...or'.","formation":"Verb-casual + ？それとも + Verb-casual + ？, etc.","examples":[{"jp":"コーヒーを飲む？それとも紅茶を飲む？","en":"Do you want to drink coffee? Or tea?","romaji":"Koohii o nomu? Sore tomo koucha o nomu?"},{"jp":"この映画は面白い？それともつまらない？","en":"Is this movie interesting? Or is it boring?","romaji":"Kono eiga wa omoshiroi? Sore tomo tsumaranai?"},{"jp":"彼は日本人だ？それとも外国人だ？","en":"Is he Japanese? Or is he a foreigner?","romaji":"Kare wa nihonjin da? Sore tomo gaikokujin da?"},{"jp":"寿司を食べに行く？それともラーメンを食べに行く？","en":"Are we going to eat sushi? Or are we going to eat ramen?","romaji":"Sushi o tabe ni iku? Sore tomo raamen o tabe ni iku?"}],"example":"コーヒーを飲む？それとも紅茶を飲む？","exampleMeaning":"Do you want to drink coffee? Or tea?"},{"pattern":"～だけしか","meaning":"Emphasizes the scarcity or insufficiency of something; 'only', 'nothing but'.","formation":"Noun/Quantity + だけ + しか + Negative Verb","examples":[{"jp":"今日は1時間だけしか勉強できなかった。","en":"Today, I could study for only one hour.","romaji":"Kyou wa ichijikan dake shika benkyou dekinakatta."},{"jp":"彼はカレーだけしか食べない。","en":"He eats only curry.","romaji":"Kare wa karee dake shika tabenai."},{"jp":"田中さんは5人だけしか招待しなかった。","en":"Tanaka only invited five people.","romaji":"Tanaka-san wa gonin dake shika shoutai shinakatta."},{"jp":"あのレストランでは野菜だけしか売っていない。","en":"That restaurant sells only vegetables.","romaji":"Ano resutoran de wa yasai dake shika utte inai."}],"example":"今日は1時間だけしか勉強できなかった。","exampleMeaning":"Today, I could study for only one hour."},{"pattern":"だけど","meaning":"Expresses a contrast or contradiction; 'but', 'however', 'even though'.","formation":"Sentence 1 + だけど + Sentence 2, or Sentence 1 + 。だけど、Sentence 2","examples":[{"jp":"試験に合格したけど、まだ勉強しなければならない。","en":"I passed the exam, but I still have to study.","romaji":"Shiken ni goukaku shita kedo, mada benkyou shinakereba naranai."},{"jp":"この部屋は広いけど、家賃が高いです。","en":"This room is spacious, but the rent is high.","romaji":"Kono heya wa hiroi kedo, yachin ga takai desu."},{"jp":"彼は優しいけど、時々厳しいです。","en":"He is kind, but sometimes strict.","romaji":"Kare wa yasashii kedo, tokidoki kibishii desu."},{"jp":"朝ごはんは作りたいけど、時間がない。","en":"I want to make breakfast, but there's no time.","romaji":"Asagohan wa tsukuritai kedo, jikan ga nai."}],"example":"試験に合格したけど、まだ勉強しなければならない。","exampleMeaning":"I passed the exam, but I still have to study."},{"pattern":"～たて","meaning":"Indicates an action that has just been completed; 'freshly', 'just'.","formation":"Verb-stem + たて","examples":[{"jp":"このパンは焼きたてで、まだ温かいです。","en":"This bread is freshly baked and still warm.","romaji":"Kono pan wa yakitate de, mada atatakai desu."},{"jp":"作りたてのお弁当が美味しい。","en":"A freshly made bento is delicious.","romaji":"Tsukuritate no obentou ga oishii."},{"jp":"洗いたてのシャツはいい匂いがする。","en":"Freshly washed shirts smell nice.","romaji":"Araitate no shatsu wa ii nioi ga suru."},{"jp":"彼女は切りたての野菜をサラダに入れました。","en":"She added freshly cut vegetables to the salad.","romaji":"Kanojo wa kiritate no yasai wo sarada ni iremashita."}],"example":"このパンは焼きたてで、まだ温かいです。","exampleMeaning":"This bread is freshly baked and still warm."},{"pattern":"～たとえ～ても (〜tatoe〜temo)","meaning":"Express a condition with 'even if'; 'no matter how'.","formation":"たとえ + Verb-casual + ても, たとえ + い-Adjective + くても, たとえ + な-Adjective + であっても, たとえ + Noun + であっても","examples":[{"jp":"たとえ雨が降っても、出かけましょう。","en":"Even if it rains, let's go out.","romaji":"Tatoe ame ga futte mo, dekakemashou."},{"jp":"たとえ彼が怒っても、本当のことを言いましょう。","en":"Even if he gets angry, let's tell the truth.","romaji":"Tatoe kare ga okotte mo, hontou no koto wo iimashou."},{"jp":"たとえ寒くても、散歩に行きたい。","en":"Even if it's cold, I want to go for a walk.","romaji":"Tatoe samukute mo, sanpo ni ikitai."},{"jp":"たとえ彼が有名であっても、彼には興味がありません。","en":"Even if he's famous, I'm not interested in him.","romaji":"Tatoe kare ga yuumei de attemo, kare ni wa kyoumi ga arimasen."}],"example":"たとえ雨が降っても、出かけましょう。","exampleMeaning":"Even if it rains, let's go out."},{"pattern":"～たところ (〜ta tokoro)","meaning":"Expresses the result or outcome of an action; 'after', 'just when', 'upon'.","formation":"Verb-た form + ところ","examples":[{"jp":"宿題をしたところ、先生からもう一つ課題が出された。","en":"Just when I finished my homework, the teacher gave us another assignment.","romaji":"Shukudai wo shita tokoro, sensei kara mou hitotsu kadai ga dasareta."},{"jp":"友達に会ったところ、彼が海外に行くと言った。","en":"Upon meeting my friend, he told me he's going abroad.","romaji":"Tomodachi ni atta tokoro, kare ga kaigai ni iku to itta."},{"jp":"食事を食べ終わったところ、電話がかかってきた。","en":"Just when I finished eating, I got a phone call.","romaji":"Shokuji wo tabeowatta tokoro, denwa ga kakatte kita."},{"jp":"机を整理したところ、忘れていたメモが見つかった。","en":"After organizing my desk, I found a memo I had forgotten about.","romaji":"Tsukue wo seiri shita tokoro, wasureteita memo ga mitsukatta."}],"example":"宿題をしたところ、先生からもう一つ課題が出された。","exampleMeaning":"Just when I finished my homework, the teacher gave us another assignment."},{"pattern":"～たとたん (〜ta totan)","meaning":"Express the moment something happens; 'as soon as', 'the moment', 'the instant'.","formation":"Verb-た form + とたん","examples":[{"jp":"ドアを開けたとたん、猫が逃げ出した。","en":"As soon as I opened the door, the cat ran away.","romaji":"Doa wo aketa totan, neko ga nigedashita."},{"jp":"電話をかけたとたん、電池が切れた。","en":"The moment I made the phone call, the battery died.","romaji":"Denwa wo kaketa totan, denchi ga kireta."},{"jp":"雨が降り始めたとたん、みんなが傘をさした。","en":"The instant it started raining, everyone put up their umbrellas.","romaji":"Ame ga furihajimeta totan, minna ga kasa wo sashita."},{"jp":"彼に会ったとたん、彼の笑顔が消えた。","en":"As soon as he met me, his smile disappeared.","romaji":"Kare ni atta totan, kare no egao ga kieta."}],"example":"ドアを開けたとたん、猫が逃げ出した。","exampleMeaning":"As soon as I opened the door, the cat ran away."},{"pattern":"～たびに (〜tabi ni)","meaning":"Express 'every time' or 'whenever'.","formation":"Verb-dictionary form + たびに, Noun + のたびに","examples":[{"jp":"彼女に会うたびに、心が弾む。","en":"Every time I meet her, my heart leaps.","romaji":"Kanojo ni au tabi ni, kokoro ga hazumu."},{"jp":"雨が降るたびに、懐かしい思い出がよみがえる。","en":"Whenever it rains, nostalgic memories come back.","romaji":"Ame ga furu tabi ni, natsukashii omoide ga yomigaeru."},{"jp":"この歌を聴くたびに、幸せな気分になる。","en":"Every time I listen to this song, I feel happy.","romaji":"Kono uta wo kiku tabi ni, shiawase na kibun ni naru."},{"jp":"家に帰るたびに、猫が出迎えてくれる。","en":"Every time I return home, the cat greets me.","romaji":"Ie ni kaeru tabi ni, neko ga demukaete kureru."}],"example":"彼女に会うたびに、心が弾む。","exampleMeaning":"Every time I meet her, my heart leaps."},{"pattern":"～だものだ (〜da mono da)","meaning":"Express the reason or cause, often used to justify something.","formation":"Verb-casual + んだものだ, い-Adjective + んだものだ, な-Adjective + なんだものだ, Noun + なんだものだ (often with から as んだものだから)","examples":[{"jp":"疲れたんだものだから、休みたい。","en":"I want to rest because I'm tired.","romaji":"Tsukareta n da mono da kara, yasumitai."},{"jp":"お腹が空いたんだものだから、何か食べたい。","en":"I want to eat something because I'm hungry.","romaji":"Onaka ga suita n da mono da kara, nanika tabetai."},{"jp":"忙しいんだものだから、来られない。","en":"I can't come because I'm busy.","romaji":"Isogashii n da mono da kara, korarenai."},{"jp":"彼は親切なんだものだから、誰も彼が好きだ。","en":"Everyone likes him because he is kind.","romaji":"Kare wa shinsetsu na n da mono da kara, dare mo kare ga suki da."}],"example":"疲れたんだものだから、休みたい。","exampleMeaning":"I want to rest because I'm tired."},{"pattern":"～ちゃった (〜chatta)","meaning":"Express an unintentional action or a regretful action; 'ended up doing', 'did accidentally'.","formation":"Verb-て/で form → ちゃった/じゃった (e.g. 食べてしまった → 食べちゃった)","examples":[{"jp":"忘れ物をしちゃった。","en":"I accidentally left something behind.","romaji":"Wasuremono o shichatta."},{"jp":"寝坊して遅刻しちゃった。","en":"I overslept and ended up being late.","romaji":"Nebou shite chikoku shichatta."},{"jp":"ケーキを全部食べちゃった。","en":"I ended up eating the whole cake.","romaji":"Keeki o zenbu tabechatta."},{"jp":"言わないつもりだったけど、言っちゃった。","en":"I wasn't planning to say it, but I ended up saying it.","romaji":"Iwanai tsumori datta kedo, icchatta."}],"example":"忘れ物をしちゃった。","exampleMeaning":"I accidentally left something behind."},{"pattern":"～ついでに (〜tsuide ni)","meaning":"Do something while or after completing another action; 'while', 'by the way'.","formation":"Verb (dictionary or た-form) + ついでに, Noun + の + ついでに, or Verb-て form + いる + ついでに","examples":[{"jp":"買い物に行くついでに、郵便局で手紙を出しましょう。","en":"Let's drop off a letter at the post office while going shopping.","romaji":"Kaimono ni iku tsuide ni, yuubinkyoku de tegami wo dashimashou."},{"jp":"図書館で本を借りたついでに、友達に会いました。","en":"I met my friend while borrowing a book from the library.","romaji":"Toshokan de hon wo karita tsuide ni, tomodachi ni aimashita."},{"jp":"日本に来たついでに、有名な観光地を訪れたいです。","en":"While visiting Japan, I'd like to see some famous tourist spots.","romaji":"Nihon ni kita tsuide ni, yuumei na kankouchi wo otozuretai desu."},{"jp":"映画館に行ったついでに、新作のポスターを見ました。","en":"While going to the movie theater, I saw a poster for a new film.","romaji":"Eigakan ni itta tsuide ni, shinsaku no posutaa wo mimashita."}],"example":"買い物に行くついでに、郵便局で手紙を出しましょう。","exampleMeaning":"Let's drop off a letter at the post office while going shopping."},{"pattern":"～っけ？ (〜kke?)","meaning":"Used to express that one is trying to recall some information.","formation":"Verb-casual + っけ?, い-Adjective + かったっけ?, な-Adjective/Noun + だっけ?","examples":[{"jp":"彼は何時に来るっけ？","en":"What time is he coming again?","romaji":"Kare wa nanji ni kuru kke?"},{"jp":"この映画、面白かったっけ？","en":"Was this movie interesting?","romaji":"Kono eiga, omoshirokatta kke?"},{"jp":"彼女は学生だっけ？","en":"She was a student, right?","romaji":"Kanojo wa gakusei dakke?"},{"jp":"すし屋はどこだっけ？","en":"Where was the sushi place again?","romaji":"Sushiya wa doko dakke?"}],"example":"彼は何時に来るっけ？","exampleMeaning":"What time is he coming again?"},{"pattern":"～っぱい (〜ppai)","meaning":"Expresses fullness or completeness; 'full', 'full of', 'filled with'.","formation":"Noun + で + いっぱい (Note: written as いっぱい, read as 'ippai')","examples":[{"jp":"部屋が荷物でいっぱいです。","en":"The room is full of luggage.","romaji":"Heya ga nimotsu de ippai desu."},{"jp":"彼女は笑顔でいっぱいでした。","en":"She was full of smiles.","romaji":"Kanojo wa egao de ippai deshita."},{"jp":"彼は仕事でいっぱいです。","en":"He is completely busy with work.","romaji":"Kare wa shigoto de ippai desu."},{"jp":"公園は花でいっぱいです。","en":"The park is filled with flowers.","romaji":"Kouen wa hana de ippai desu."}],"example":"部屋が荷物でいっぱいです。","exampleMeaning":"The room is full of luggage."},{"pattern":"～っぱなし (〜ppanashi)","meaning":"Indicate a state where an action is left as is (unchanged or unfinished).","formation":"Verb-ますstem + っぱなし","examples":[{"jp":"窓を開けっぱなしにすると、虫が入ってくる。","en":"If you leave the window open, bugs will come in.","romaji":"Mado o akeppanashi ni suru to, mushi ga haitte kuru."},{"jp":"洗濯物を干しっぱなしで、雨に濡れた。","en":"I left the laundry hanging out, and it got wet in the rain.","romaji":"Sentakumono o hoshippanashi de, ame ni nureta."},{"jp":"彼はドアを開けっぱなしにして出かけた。","en":"He went out leaving the door open.","romaji":"Kare wa doa o akeppanashi ni shite dekaketa."},{"jp":"テレビをつけっぱなしにして寝てしまった。","en":"I fell asleep with the TV left on.","romaji":"Terebi o tsukeppanashi ni shite nete shimatta."}],"example":"窓を開けっぱなしにすると、虫が入ってくる。","exampleMeaning":"If you leave the window open, bugs will come in."},{"pattern":"～つまり (〜tsumari)","meaning":"Summarizing, restating, or clarifying a point: 'in other words', 'that is to say'.","formation":"Sentence A + つまり + Sentence B (rephrasing)","examples":[{"jp":"彼は大学の教授です。つまり、専門家です。","en":"He is a university professor. In other words, he is an expert.","romaji":"Kare wa daigaku no kyouju desu. Tsumari, senmonka desu."},{"jp":"今日は土曜日だ。つまり、明日は日曜日だ。","en":"Today is Saturday. That is to say, tomorrow is Sunday.","romaji":"Kyou wa doyoubi da. Tsumari, ashita wa nichiyoubi da."},{"jp":"山田さんは友達のお姉さんです。つまり、私たちの知り合いです。","en":"Ms. Yamada is my friend's older sister. In short, she's someone we know.","romaji":"Yamada-san wa tomodachi no oneesan desu. Tsumari, watashitachi no shiriai desu."},{"jp":"彼女はフランス出身です。つまり、フランス語が話せます。","en":"She is from France. In other words, she can speak French.","romaji":"Kanojo wa Furansu shusshin desu. Tsumari, Furansugo ga hanasemasu."}],"example":"彼は大学の教授です。つまり、専門家です。","exampleMeaning":"He is a university professor. In other words, he is an expert."},{"pattern":"～つもりでした (〜tsumori deshita)","meaning":"Expressing a past intention or plan; 'was planning to', 'meant to'.","formation":"Verb-casual (dictionary form) + つもりでした","examples":[{"jp":"昨日は友達に会うつもりでしたが、風邪を引いてしまいました。","en":"I was planning to meet my friend yesterday, but I caught a cold.","romaji":"Kinou wa tomodachi ni au tsumori deshita ga, kaze o hiite shimaimashita."},{"jp":"映画を見るつもりでしたが、時間がなくなりました。","en":"I intended to watch a movie, but I ran out of time.","romaji":"Eiga o miru tsumori deshita ga, jikan ga nakunarimashita."},{"jp":"彼らが来るつもりでしたが、電話でキャンセルされました。","en":"They were supposed to come, but they canceled by phone.","romaji":"Karera ga kuru tsumori deshita ga, denwa de kyanseru saremashita."},{"jp":"この本を読むつもりでしたが、もう読み終わっていました。","en":"I meant to read this book, but I realized I'd already finished it.","romaji":"Kono hon o yomu tsumori deshita ga, mou yomiowatte imashita."}],"example":"昨日は友達に会うつもりでしたが、風邪を引いてしまいました。","exampleMeaning":"I was planning to meet my friend yesterday, but I caught a cold."},{"pattern":"～てくれと (〜te kureto)","meaning":"Quote someone's request (telling someone to do something).","formation":"Verb-て form + くれと (言う / 頼む / 伝える, etc.)","examples":[{"jp":"電話をかけてくれと言われました。","en":"I was told to make a phone call.","romaji":"Denwa o kakete kureto iwaremashita."},{"jp":"この荷物を運んでくれと頼まれました。","en":"I was asked to carry this luggage.","romaji":"Kono nimotsu o hakonde kureto tanomaremashita."},{"jp":"最後まで待ってくれとお願いされました。","en":"I was asked to wait until the end.","romaji":"Saigo made matte kureto onegai saremashita."},{"jp":"休んでくれと言われました。","en":"I was told to please take a rest.","romaji":"Yasunde kureto iwaremashita."}],"example":"電話をかけてくれと言われました。","exampleMeaning":"I was told to make a phone call."},{"pattern":"～てごらん (〜te goran)","meaning":"Suggest or invite someone to try doing something; 'Why don't you try...'.","formation":"Verb-て form + ごらん","examples":[{"jp":"そのゲームをやってごらん。","en":"Why don't you try playing that game?","romaji":"Sono geemu o yatte goran."},{"jp":"彼に話してごらん。","en":"Try talking to him.","romaji":"Kare ni hanashite goran."},{"jp":"新しいレシピを作ってごらん。","en":"Why don't you try making a new recipe?","romaji":"Atarashii reshipi o tsukutte goran."},{"jp":"そのドレスを着てごらん。","en":"Try putting on that dress.","romaji":"Sono doresu o kite goran."}],"example":"そのゲームをやってごらん。","exampleMeaning":"Why don't you try playing that game?"},{"pattern":"ですから～","meaning":"Expresses reason or cause; 'because', 'since', 'so'.","formation":"Sentence A + ですから + Sentence B","examples":[{"jp":"今日は寒いですから、コートを着てください。","en":"It's cold today, so please wear a coat.","romaji":"Kyou wa samui desu kara, kooto o kite kudasai."},{"jp":"この映画は面白いですから、ぜひ見てください。","en":"This movie is interesting, so please watch it.","romaji":"Kono eiga wa omoshiroi desu kara, zehi mite kudasai."},{"jp":"明日は休みですから、ゆっくり休んでください。","en":"Tomorrow is a day off, so please take your time to rest.","romaji":"Ashita wa yasumi desu kara, yukkuri yasunde kudasai."},{"jp":"彼は親切ですから、手伝ってくれるでしょう。","en":"He's kind, so he'll probably help you.","romaji":"Kare wa shinsetsu desu kara, tetsudatte kureru deshou."}],"example":"今日は寒いですから、コートを着てください。","exampleMeaning":"It's cold today, so please wear a coat."},{"pattern":"～てはじめて (〜te hajimete)","meaning":"Realization or action done for the first time; 'only after', 'not until'.","formation":"Verb-て form + はじめて","examples":[{"jp":"海外に行ってはじめて、日本の良さが分かりました。","en":"Only after going abroad did I realize how great Japan is.","romaji":"Kaigai ni itte hajimete, Nihon no yosa ga wakarimashita."},{"jp":"彼女と別れてはじめて、彼女の大切さに気づいた。","en":"I realized her importance only after breaking up with her.","romaji":"Kanojo to wakarete hajimete, kanojo no taisetsusa ni kizuita."},{"jp":"大学を卒業してはじめて、学生時代の楽しさが分かった。","en":"I understood how fun my student days were only after graduating from university.","romaji":"Daigaku o sotsugyou shite hajimete, gakusei jidai no tanoshisa ga wakatta."},{"jp":"子供ができてはじめて、親の気持ちが分かった。","en":"I understood how parents feel only after I had a child.","romaji":"Kodomo ga dekite hajimete, oya no kimochi ga wakatta."}],"example":"海外に行ってはじめて、日本の良さが分かりました。","exampleMeaning":"Only after going abroad did I realize how great Japan is."},{"pattern":"～てほしい (〜te hoshii)","meaning":"Express a desire for someone else to do something; 'I want you to do...'.","formation":"Verb-て form + ほしい","examples":[{"jp":"子供にもっと勉強してほしい。","en":"I want my child to study more.","romaji":"Kodomo ni motto benkyou shite hoshii."},{"jp":"彼に私に電話してほしい。","en":"I want him to call me.","romaji":"Kare ni watashi ni denwa shite hoshii."},{"jp":"友達に手伝ってほしい。","en":"I want my friend to help me.","romaji":"Tomodachi ni tetsudatte hoshii."},{"jp":"彼女に明日ここに来てほしい。","en":"I want her to come here tomorrow.","romaji":"Kanojo ni ashita koko ni kite hoshii."}],"example":"子供にもっと勉強してほしい。","exampleMeaning":"I want my child to study more."},{"pattern":"～ても (〜temo)","meaning":"'Even if', 'even though', or 'although'.","formation":"Verb-て form + も, い-Adjective (～く) + ても, な-Adjective/Noun (～で) + も","examples":[{"jp":"雨が降っても、運動会は開催されます。","en":"Even if it rains, the sports festival will be held.","romaji":"Ame ga futte mo, undoukai wa kaisai saremasu."},{"jp":"忙しくても、毎日勉強する時間を作る。","en":"Even though I'm busy, I make time to study every day.","romaji":"Isogashikute mo, mainichi benkyou suru jikan o tsukuru."},{"jp":"高くても、良い品質のものを買います。","en":"Even if it's expensive, I'll buy something of good quality.","romaji":"Takakute mo, yoi hinshitsu no mono o kaimasu."},{"jp":"彼女が有名人でも、私は彼女のことを知らない。","en":"Even if she's famous, I don't know her.","romaji":"Kanojo ga yuumeijin demo, watashi wa kanojo no koto o shiranai."}],"example":"雨が降っても、運動会は開催されます。","exampleMeaning":"Even if it rains, the sports festival will be held."},{"pattern":"～といいなあ (〜to ii naa)","meaning":"Express a wish or hope; 'it would be nice if', 'I hope that'.","formation":"Verb-casual + といいなあ, い-Adjective + といいなあ, な-Adjective + だといいなあ, Noun + だといいなあ","examples":[{"jp":"明日晴れるといいなあ。","en":"I hope it's sunny tomorrow.","romaji":"Ashita hareru to ii naa."},{"jp":"この試験に合格するといいなあ。","en":"I hope I pass this exam.","romaji":"Kono shiken ni goukaku suru to ii naa."},{"jp":"彼女が元気だといいなあ。","en":"I hope she is doing well.","romaji":"Kanojo ga genki da to ii naa."},{"jp":"彼が新しい仕事が見つかるといいなあ。","en":"I hope he finds a new job.","romaji":"Kare ga atarashii shigoto ga mitsukaru to ii naa."}],"example":"明日晴れるといいなあ。","exampleMeaning":"I hope it's sunny tomorrow."},{"pattern":"～という (〜to iu)","meaning":"Used for quoting, defining, or giving an example; 'called', 'that is to say', 'like'.","formation":"Noun + という + Noun, Verb-casual + という + Noun, い-Adjective + という + Noun, な-Adjective + という + Noun","examples":[{"jp":"本屋で「ハリー・ポッター」という本を買いました。","en":"I bought a book called 'Harry Potter' at the bookstore.","romaji":"Hon'ya de 'Harry Potter' to iu hon o kaimashita."},{"jp":"昨日、美味しいというケーキを食べました。","en":"Yesterday, I ate a cake that is said to be delicious.","romaji":"Kinou, oishii to iu keeki o tabemashita."},{"jp":"彼はとても親切だという評判です。","en":"He has a reputation for being very kind.","romaji":"Kare wa totemo shinsetsu da to iu hyouban desu."},{"jp":"今年の夏、東京にある「ディズニーランド」というテーマパークに行きたいです。","en":"I want to go to a theme park called 'Disneyland' in Tokyo this summer.","romaji":"Kotoshi no natsu, Toukyou ni aru 'Disneyland' to iu teema paaku ni ikitai desu."}],"example":"本屋で「ハリー・ポッター」という本を買いました。","exampleMeaning":"I bought a book called 'Harry Potter' at the bookstore."},{"pattern":"～ということだ (〜to iu koto da)","meaning":"Express a conclusion or hearsay; 'I heard', 'it means', 'it can be said'.","formation":"Verb-casual + ということだ, い-Adjective + ということだ, な-Adjective + だということだ, Noun + だということだ","examples":[{"jp":"彼は来週結婚するということだ。","en":"I heard that he is getting married next week.","romaji":"Kare wa raishuu kekkon suru to iu koto da."},{"jp":"この試験は難しいということだ。","en":"It means this exam is difficult.","romaji":"Kono shiken wa muzukashii to iu koto da."},{"jp":"彼女が引っ越したということだ。","en":"I heard that she has moved.","romaji":"Kanojo ga hikkoshita to iu koto da."},{"jp":"彼は仕事がうまくいかないだということだ。","en":"It can be said that his work is not going well.","romaji":"Kare wa shigoto ga umaku ikanai da to iu koto da."}],"example":"彼は来週結婚するということだ。","exampleMeaning":"I heard that he is getting married next week."},{"pattern":"～というと (〜to iu to)","meaning":"Used to provide an example or characteristic related to the topic; 'when it comes to', 'speaking of'.","formation":"Noun + というと","examples":[{"jp":"日本料理というと、寿司が思い浮かぶ。","en":"When it comes to Japanese cuisine, sushi comes to mind.","romaji":"Nihon ryouri to iu to, sushi ga omoiukabu."},{"jp":"パリというと、エッフェル塔を思い出す。","en":"Speaking of Paris, I recall the Eiffel Tower.","romaji":"Pari to iu to, Efferu Tou wo omoidasu."},{"jp":"夏休みというと、海に行くことが楽しみだ。","en":"When it comes to summer vacation, I look forward to going to the beach.","romaji":"Natsu yasumi to iu to, umi ni iku koto ga tanoshimi da."},{"jp":"彼というと、いつも元気な人だと思う。","en":"Speaking of him, I think he's always energetic.","romaji":"Kare to iu to, itsumo genki na hito da to omou."}],"example":"日本料理というと、寿司が思い浮かぶ。","exampleMeaning":"When it comes to Japanese cuisine, sushi comes to mind."},{"pattern":"～というの～ (〜to iu no〜)","meaning":"Explain or emphasize the reason for a situation or action.","formation":"Verb-casual + というの, い-Adjective + というの, な-Adjective + だというの, Noun + だというの","examples":[{"jp":"遅刻したのは、電車が遅れたというのだ。","en":"The reason I was late is because the train was delayed.","romaji":"Chikoku shita no wa, densha ga okureta to iu no da."},{"jp":"この部屋が汚いのは、掃除をしなかったというのだ。","en":"The reason this room is dirty is because I didn't clean it.","romaji":"Kono heya ga kitanai no wa, souji o shinakatta to iu no da."},{"jp":"彼女が怒っているのは、彼が約束を破ったというのだ。","en":"The reason she is angry is that he broke his promise.","romaji":"Kanojo ga okotte iru no wa, kare ga yakusoku o yabutta to iu no da."},{"jp":"彼が成功したのは、努力して勉強したというのだ。","en":"The reason he succeeded is because he studied hard.","romaji":"Kare ga seikou shita no wa, doryoku shite benkyou shita to iu no da."}],"example":"遅刻したのは、電車が遅れたというのだ。","exampleMeaning":"The reason I was late is because the train was delayed."},{"pattern":"～というのは (〜to iu no wa)","meaning":"Used to provide an explanation or definition; 'that is to say...', 'by that, I mean...'.","formation":"Phrase/sentence + というのは + explanation/definition","examples":[{"jp":"日本に行くというのは、日本に旅行することです。","en":"Going to Japan, that is to say, traveling to Japan.","romaji":"Nihon ni iku to iu no wa, Nihon ni ryokou suru koto desu."},{"jp":"この問題は難しいというのは、解決に時間がかかるということです。","en":"When I say this problem is difficult, I mean it takes time to solve.","romaji":"Kono mondai wa muzukashii to iu no wa, kaiketsu ni jikan ga kakaru to iu koto desu."},{"jp":"彼が怒っているというのは、彼が不満を感じているということです。","en":"By saying that he's angry, I mean he's feeling dissatisfied.","romaji":"Kare ga okotteiru to iu no wa, kare ga fuman wo kanjiteiru to iu koto desu."},{"jp":"太るというのは、体重が増えるということです。","en":"Gaining weight, that is to say, increasing one's body weight.","romaji":"Futoru to iu no wa, taijuu ga fueru to iu koto desu."}],"example":"日本に行くというのは、日本に旅行することです。","exampleMeaning":"Going to Japan, that is to say, traveling to Japan."},{"pattern":"～というより (〜to iu yori)","meaning":"Express a comparison with preference; 'rather than', 'more like', 'instead of'.","formation":"Verb-casual + というより, い-Adjective + というより, な-Adjective + だというより, Noun + だというより","examples":[{"jp":"この部屋は狭いというより、居心地がいい。","en":"Rather than saying this room is small, it's more like it's cozy.","romaji":"Kono heya wa semai to iu yori, igokochi ga ii."},{"jp":"彼は怖いというより、頼りがいがある。","en":"Instead of saying he's scary, he's more like a reliable person.","romaji":"Kare wa kowai to iu yori, tayori gai ga aru."},{"jp":"映画はつまらないというより、ちょっと長かった。","en":"Rather than calling the movie boring, I'd say it was a bit long.","romaji":"Eiga wa tsumaranai to iu yori, chotto nagakatta."},{"jp":"彼女は友達だというより、家族のような存在だ。","en":"Rather than a friend, she's more like family.","romaji":"Kanojo wa tomodachi da to iu yori, kazoku no you na sonzai da."}],"example":"この部屋は狭いというより、居心地がいい。","exampleMeaning":"Rather than saying this room is small, it's more like it's cozy."},{"pattern":"～といっても (〜to ittemo)","meaning":"Express the meaning 'even though', 'although', 'but'.","formation":"Verb-casual + といっても, い-Adjective + といっても, な-Adjective + だといっても, Noun + だといっても","examples":[{"jp":"彼は有名だといっても、みんなに知られているわけではありません。","en":"Even though he's famous, it doesn't mean everyone knows him.","romaji":"Kare wa yuumei da to ittemo, minna ni shirarete iru wake de wa arimasen."},{"jp":"このスープは辛いといっても、私にはちょうどいいです。","en":"Although this soup is spicy, it's just right for me.","romaji":"Kono suupu wa karai to ittemo, watashi ni wa choudo ii desu."},{"jp":"彼女は若いですが、経験があるといっても、まだ新人です。","en":"She's young, and although she has some experience, she's still a newcomer.","romaji":"Kanojo wa wakai desu ga, keiken ga aru to ittemo, mada shinjin desu."},{"jp":"このレストランは高いだといっても、美味しい料理が食べられるので価値があります。","en":"Even though this restaurant is expensive, it's worth it because you can enjoy delicious dishes.","romaji":"Kono resutoran wa takai da to ittemo, oishii ryouri ga taberareru node kachi ga arimasu."}],"example":"彼は有名だといっても、みんなに知られているわけではありません。","exampleMeaning":"Even though he's famous, it doesn't mean everyone knows him."},{"pattern":"～とおり (〜toori)","meaning":"Expresses that something is done 'as is', 'as stated', or 'as instructed'.","formation":"Verb-て form + とおり, Noun + のとおり","examples":[{"jp":"先生が言ったとおり、宿題をやりました。","en":"I did my homework exactly as the teacher said.","romaji":"Sensei ga itta toori, shukudai wo yarimashita."},{"jp":"地図に書いてあるとおりに行けば、駅に着きます。","en":"If you follow what's written on the map, you'll arrive at the station.","romaji":"Chizu ni kaite aru toori ni ikeba, eki ni tsukimasu."},{"jp":"レシピのとおりにケーキを作った。","en":"I baked the cake according to the recipe.","romaji":"Reshipi no toori ni keeki o tsukutta."},{"jp":"彼女は約束したとおりに時間通りに来ました。","en":"She arrived on time, just as she promised.","romaji":"Kanojo wa yakusoku shita toori ni jikan doori ni kimashita."}],"example":"先生が言ったとおり、宿題をやりました。","exampleMeaning":"I did my homework exactly as the teacher said."},{"pattern":"～とく (〜toku)","meaning":"Express doing something in advance or for future convenience (casual form of ～ておく).","formation":"Verb-て form + とく (e.g., 食べておく→食べとく, 読んでおく→読んどく)","examples":[{"jp":"夜遅くなるから、今晩のご飯を作っとく。","en":"Since it will be late tonight, I'll prepare dinner in advance.","romaji":"Yoru osoku naru kara, konban no gohan wo tsukutoku."},{"jp":"傘が必要かもしれないので、持っておく。","en":"I might need an umbrella, so I'll bring one along (just in case).","romaji":"Kasa ga hitsuyou kamoshirenai node, motte oku."},{"jp":"試験が近いから、今から勉強しとこう。","en":"The exam is coming up, so I'll start studying now.","romaji":"Shiken ga chikai kara, ima kara benkyou shitokou."},{"jp":"明日は忙しいので、洗濯をしとく。","en":"Since I'll be busy tomorrow, I'll do the laundry in advance.","romaji":"Ashita wa isogashii node, sentaku wo shitoku."}],"example":"夜遅くなるから、今晩のご飯を作っとく。","exampleMeaning":"Since it will be late tonight, I'll prepare dinner in advance."},{"pattern":"～ところが (〜tokoro ga)","meaning":"Expresses a contrast or unexpected outcome; 'however', 'but', 'even though'.","formation":"Phrase 1 (expected situation) + ところが + Phrase 2 (unexpected result)","examples":[{"jp":"彼はいつも遅刻するところが、今日は早く来ました。","en":"He's always late, but today he arrived early.","romaji":"Kare wa itsumo chikoku suru tokoro ga, kyou wa hayaku kimashita."},{"jp":"昨日は暑かったところが、今日は寒くなりました。","en":"Yesterday was hot, but today it got cold.","romaji":"Kinou wa atsukatta tokoro ga, kyou wa samuku narimashita."},{"jp":"試合で負けると思ったところが、意外にも勝ちました。","en":"I thought we would lose the match, but surprisingly we won.","romaji":"Shiai de makeru to omotta tokoro ga, igai ni mo kachimashita."},{"jp":"決勝戦で優勝するところが、最後のポイントで負けました。","en":"We were about to win the final, but we lost at the last point.","romaji":"Kesshousen de yuushou suru tokoro ga, saigo no pointo de makemashita."}],"example":"彼はいつも遅刻するところが、今日は早く来ました。","exampleMeaning":"He's always late, but today he arrived early."},{"pattern":"～ところだった (〜tokoro datta)","meaning":"Expresses a near miss or a situation that almost happened; 'was just about to', 'almost', 'nearly'.","formation":"Verb (dictionary form or ている form) + ところだった","examples":[{"jp":"もう少しで遅れるところだった。","en":"I was just about to be late.","romaji":"Mou sukoshi de okureru tokoro datta."},{"jp":"彼が危うく事故にあうところだった。","en":"He almost had an accident.","romaji":"Kare ga ayauku jiko ni au tokoro datta."},{"jp":"電車に乗るところだったが、ドアが閉まってしまった。","en":"I was just about to get on the train, but the door closed.","romaji":"Densha ni noru tokoro datta ga, doa ga shimatte shimatta."},{"jp":"忘れ物をするところだった。","en":"I almost forgot my belongings.","romaji":"Wasuremono wo suru tokoro datta."}],"example":"もう少しで遅れるところだった。","exampleMeaning":"I was just about to be late."},{"pattern":"ところで","meaning":"Used for changing the topic or bringing up a new topic; 'by the way', 'speaking of'.","formation":"ところで + new topic or question","examples":[{"jp":"ところで、昨日の宿題はもう終わりましたか？","en":"By the way, did you finish yesterday's homework?","romaji":"Tokorode, kinou no shukudai wa mou owari mashita ka?"},{"jp":"彼はプールで泳いでいます。ところで、お昼ご飯は何にしますか？","en":"He is swimming in the pool. By the way, what do you want for lunch?","romaji":"Kare wa puuru de oyoide imasu. Tokorode, ohiru gohan wa nani ni shimasu ka?"},{"jp":"昨日は楽しかったですね。ところで、この写真を見ましたか？","en":"Yesterday was fun, wasn't it? By the way, did you see this photo?","romaji":"Kinou wa tanoshikatta desu ne. Tokorode, kono shashin wo mimashita ka?"},{"jp":"ところで、明日の会議の時間を知っていますか？","en":"By the way, do you know the time of tomorrow's meeting?","romaji":"Tokorode, ashita no kaigi no jikan wo shitte imasu ka?"}],"example":"ところで、昨日の宿題はもう終わりましたか？","exampleMeaning":"By the way, did you finish yesterday's homework?"},{"pattern":"～としたら (〜to shitara)","meaning":"Express a hypothetical situation; 'if', 'suppose', 'assuming'.","formation":"Verb-casual + としたら, い-Adjective + としたら, な-Adjective + だとしたら, Noun + だとしたら","examples":[{"jp":"明日雨が降るとしたら、傘を持って行きましょう。","en":"If it rains tomorrow, let's bring an umbrella.","romaji":"Ashita ame ga furu to shitara, kasa wo motte ikimashou."},{"jp":"このケーキが美味しくないとしたら、誰も食べないでしょう。","en":"If this cake is not delicious, nobody will eat it.","romaji":"Kono keeki ga oishikunai to shitara, daremo tabenai deshou."},{"jp":"彼が病気だとしたら、すぐに病院に行かせてあげてください。","en":"If he is sick, please take him to the hospital right away.","romaji":"Kare ga byouki da to shitara, sugu ni byouin ni ikasete agete kudasai."},{"jp":"彼女が学生だとしたら、このレストランは割引があるでしょう。","en":"If she is a student, there will be a discount at this restaurant.","romaji":"Kanojo ga gakusei da to shitara, kono resutoran wa waribiki ga aru deshou."}],"example":"明日雨が降るとしたら、傘を持って行きましょう。","exampleMeaning":"If it rains tomorrow, let's bring an umbrella."},{"pattern":"～として (〜to shite)","meaning":"Indicates a role, capacity, or identity; 'as', 'in the capacity of'.","formation":"Verb-casual + として, い-Adjective + として, な-Adjective + だとして, Noun + だとして","examples":[{"jp":"彼は弁護士として働いています。","en":"He is working as a lawyer.","romaji":"Kare wa bengoshi to shite hataraite imasu."},{"jp":"この料理はスナックとして食べられます。","en":"This dish can be eaten as a snack.","romaji":"Kono ryouri wa sunakku to shite taberaremasu."},{"jp":"彼女はリーダーとして尊敬されている。","en":"She is respected as a leader.","romaji":"Kanojo wa riidaa to shite sonkei sarete iru."},{"jp":"この本は参考書として使われます。","en":"This book is used as a reference.","romaji":"Kono hon wa sankousho to shite tsukawaremasu."}],"example":"彼は弁護士として働いています。","exampleMeaning":"He is working as a lawyer."},{"pattern":"～どんなに～ことか (〜donna ni〜koto ka)","meaning":"Expresses the extent of something or emphasizes the degree of a condition or situation.","formation":"どんなに + Adjective + ことか, どんなに + Verb + ことか","examples":[{"jp":"どんなに疲れたことか、言葉では表せません。","en":"I can't put into words how tired I am.","romaji":"Donna ni tsukareta koto ka, kotoba de wa arawasemasen."},{"jp":"どんなに辛いことか、彼女は毎日頑張って働いています。","en":"How hard it must be, she works hard every day.","romaji":"Donna ni tsurai koto ka, kanojo wa mainichi ganbatte hataraiteimasu."},{"jp":"彼の成功はどんなに喜ばしいことか。","en":"How happy his success must be.","romaji":"Kare no seikou wa donna ni yorokobashii koto ka."},{"jp":"どんなに楽しいことか、みんなで旅行に行く。","en":"How fun it is to go on a trip with everyone.","romaji":"Donna ni tanoshii koto ka, minna de ryokou ni iku."}],"example":"どんなに疲れたことか、言葉では表せません。","exampleMeaning":"I can't put into words how tired I am."},{"pattern":"どんなに～ても","meaning":"Expresses 'no matter how much' or 'even if'; emphasizes the degree of a situation.","formation":"どんなに + Verb-てform + も, どんなに + い-Adjective-てform + も, どんなに + な-Adjective + でも","examples":[{"jp":"どんなに勉強しても、まだわからないことがある。","en":"No matter how much I study, there are still things I don't understand.","romaji":"Donna ni benkyou shite mo, mada wakaranai koto ga aru."},{"jp":"どんなに速く走っても、彼には勝てません。","en":"No matter how fast I run, I can't beat him.","romaji":"Donna ni hayaku hashitte mo, kare ni wa katemasen."},{"jp":"どんなに疲れても、仕事を終わらせるまで帰れません。","en":"No matter how tired I am, I can't go home until I finish my work.","romaji":"Donna ni tsukarete mo, shigoto o owaraseru made kaeremasen."},{"jp":"どんなに美味しくても、これ以上食べられない。","en":"No matter how delicious it is, I can't eat any more.","romaji":"Donna ni oishikute mo, kore ijou taberarenai."}],"example":"どんなに勉強しても、まだわからないことがある。","exampleMeaning":"No matter how much I study, there are still things I don't understand."},{"pattern":"～ないことはない (〜nai koto wa nai)","meaning":"Express the idea that 'it's not that it's impossible' or 'it's not that it cannot be done'.","formation":"Verb-ない form + ことはない","examples":[{"jp":"この問題を解けないことはないが、時間がかかりそうだ。","en":"It's not that I can't solve this problem, but it seems like it will take time.","romaji":"Kono mondai wo tokenai koto wa nai ga, jikan ga kakari sou da."},{"jp":"彼に会わないことはないけど、あまり話したくない。","en":"It's not that I can't meet him, but I don't really want to talk.","romaji":"Kare ni awanai koto wa nai kedo, amari hanashitakunai."},{"jp":"この映画を見ないことはないけれど、他の映画がもっと面白いと思う。","en":"It's not that I cannot watch this movie, but I think other movies are more interesting.","romaji":"Kono eiga wo minai koto wa nai keredo, hoka no eiga ga motto omoshiroi to omou."},{"jp":"その本を読まないことはないが、長いので気をつけてください。","en":"It's not that I can't read that book, but it's long, so be careful.","romaji":"Sono hon wo yomanai koto wa nai ga, nagai node ki wo tsukete kudasai."}],"example":"この問題を解けないことはないが、時間がかかりそうだ。","exampleMeaning":"It's not that I can't solve this problem, but it seems like it will take time."},{"pattern":"～ないと (〜nai to)","meaning":"Express a condition; 'if... not', 'unless', 'must'.","formation":"Verb-negative form + ないと","examples":[{"jp":"朝食を食べないと、お腹が空く。","en":"If I don't eat breakfast, I will be hungry.","romaji":"Asa gohan wo tabenai to, onaka ga suku."},{"jp":"宿題をしないと、先生に怒られる。","en":"If I don't do my homework, the teacher will be angry.","romaji":"Shukudai wo shinai to, sensei ni okorareru."},{"jp":"充電をしないと、電話が使えなくなる。","en":"If I don't charge it, I won't be able to use the phone.","romaji":"Juden wo shinai to, denwa ga tsukaenaku naru."},{"jp":"この事故を報告しないと、問題が大きくなる。","en":"If I don't report this accident, the problem will become bigger.","romaji":"Kono jiko wo houkoku shinai to, mondai ga ookiku naru."}],"example":"朝食を食べないと、お腹が空く。","exampleMeaning":"If I don't eat breakfast, I will be hungry."},{"pattern":"～なぜなら (〜nazenara)","meaning":"Express a reason or explanation; 'because', 'the reason is'.","formation":"Sentence/Statement + なぜなら + Reason + から/だから","examples":[{"jp":"このレストランが大好きだ。なぜなら料理が美味しいから。","en":"I love this restaurant because the food is delicious.","romaji":"Kono resutoran ga daisuki da. Nazenara ryouri ga oishii kara."},{"jp":"彼女は試験に合格しなかった。なぜなら勉強しなかったから。","en":"She didn't pass the exam because she didn't study.","romaji":"Kanojo wa shiken ni goukaku shinakatta. Nazenara benkyou shinakatta kara."},{"jp":"私は映画を見に行かない。なぜなら今日は忙しいから。","en":"I won't go to see a movie because I am busy today.","romaji":"Watashi wa eiga o mi ni ikanai. Nazenara kyou wa isogashii kara."},{"jp":"彼はこのプロジェクトを任せられる。なぜなら経験が豊富だから。","en":"He can be trusted with this project because he has a wealth of experience.","romaji":"Kare wa kono purojekuto wo makaserareru. Nazenara keiken ga houfu dakara."}],"example":"このレストランが大好きだ。なぜなら料理が美味しいから。","exampleMeaning":"I love this restaurant because the food is delicious."},{"pattern":"～など (〜nado)","meaning":"Indicates a non-exhaustive list of examples; 'such as', 'things like', 'among others'.","formation":"Noun + など","examples":[{"jp":"魚、果物などを市場で買いました。","en":"I bought fish, fruits, and such at the market.","romaji":"Sakana, kudamono nado wo ichiba de kaimashita."},{"jp":"彼は日本語、英語、中国語などを話せます。","en":"He can speak languages such as Japanese, English, and Chinese.","romaji":"Kare wa nihongo, eigo, chuugokugo nado wo hanasemasu."},{"jp":"美術館では絵画、彫刻などの作品を見ました。","en":"At the art museum, I saw works like paintings, sculptures, and others.","romaji":"Bijutsukan de wa kaiga, choukoku nado no sakuhin wo mimashita."},{"jp":"この店ではパン、ケーキなどのお菓子を売っています。","en":"This store sells sweets such as bread, cakes, and so on.","romaji":"Kono mise de wa pan, keeki nado no okashi wo utteimasu."}],"example":"魚、果物などを市場で買いました。","exampleMeaning":"I bought fish, fruits, and such at the market."},{"pattern":"～なんか (〜nanka)","meaning":"Expresses the idea of 'things like' or 'something like', used for listing examples or downplaying something.","formation":"Noun + なんか, Verb-casual + なんか, い-Adjective + なんか, な-Adjective + なんか","examples":[{"jp":"お金なんかいらない。","en":"I don't need money or anything like that.","romaji":"Okane nanka iranai."},{"jp":"彼はピアノなんかも弾けます。","en":"He can play things like the piano.","romaji":"Kare wa piano nanka mo hikemasu."},{"jp":"忙しいなんかじゃないよ。","en":"I'm not really busy or anything like that.","romaji":"Isogashii nanka janai yo."},{"jp":"彼女は親切なんかじゃない。","en":"She's not kind or anything like that.","romaji":"Kanojo wa shinsetsu nanka janai."}],"example":"お金なんかいらない。","exampleMeaning":"I don't need money or anything like that."},{"pattern":"～において (〜ni oite)","meaning":"Indicates the place, time, or context where an action or situation takes place.","formation":"Noun (Place/Time/Context) + において","examples":[{"jp":"日本において、お盆は家族が集まる大切な行事です。","en":"In Japan, Obon is an important event where families gather.","romaji":"Nihon ni oite, obon wa kazoku ga atsumaru taisetsu na gyouji desu."},{"jp":"会議において、彼の意見が一番説得力がありました。","en":"In the meeting, his opinion was the most persuasive.","romaji":"Kaigi ni oite, kare no iken ga ichiban settokuryoku ga arimashita."},{"jp":"科学の分野において、研究が日々進んでいます。","en":"In the field of science, research is advancing daily.","romaji":"Kagaku no bun'ya ni oite, kenkyuu ga hibi susunde imasu."},{"jp":"幼少期において、子供たちは勢いよく物を覚えます。","en":"During early childhood, children learn things rapidly.","romaji":"Youshouki ni oite, kodomo-tachi wa ikioi yoku mono wo oboemasu."}],"example":"日本において、お盆は家族が集まる大切な行事です。","exampleMeaning":"In Japan, Obon is an important event where families gather."},{"pattern":"～にかわって (〜ni kawatte)","meaning":"Expresses 'in place of', 'on behalf of', or 'instead of'.","formation":"Noun + にかわって","examples":[{"jp":"彼が病気なので、私が会議に出席することになりました。私が彼にかわって会議に出席します。","en":"He is sick, so I will attend the meeting. I will attend the meeting on his behalf.","romaji":"Kare ga byouki na no de, watashi ga kaigi ni shusseki suru koto ni narimashita. Watashi ga kare ni kawatte kaigi ni shusseki shimasu."},{"jp":"母は忙しいので、私が母にかわって料理を作ります。","en":"My mother is busy, so I will cook the meal instead of her.","romaji":"Haha wa isogashii no de, watashi ga haha ni kawatte ryouri wo tsukurimasu."},{"jp":"今度の旅行は妹にかわって、私が一緒に行きます。","en":"For this trip, I will go together instead of my younger sister.","romaji":"Kondo no ryokou wa imouto ni kawatte, watashi ga issho ni ikimasu."},{"jp":"先生が出張中でいないので、助手が先生にかわってクラスを担当します。","en":"The teacher is not here because of a business trip, so the assistant will take charge of the class instead of the teacher.","romaji":"Sensei ga shucchou chuu de inai no de, joshu ga sensei ni kawatte kurasu wo tantou shimasu."}],"example":"彼が病気なので、私が会議に出席することになりました。私が彼にかわって会議に出席します。","exampleMeaning":"He is sick, so I will attend the meeting. I will attend the meeting on his behalf."},{"pattern":"～にしては (〜ni shite wa)","meaning":"Express 'for' or 'considering' in the sense of being unusual or unexpected.","formation":"Verb-casual + にしては, い-Adjective + にしては, な-Adjective + にしては, Noun + にしては","examples":[{"jp":"彼女は初心者にしては、上手に水泳ができる。","en":"Considering she is a beginner, she can swim well.","romaji":"Kanojo wa shoshinsha ni shite wa, jouzu ni suiei ga dekiru."},{"jp":"このお寿司は安いにしては、とても美味しい。","en":"Considering this sushi is cheap, it's very delicious.","romaji":"Kono o-sushi wa yasui ni shite wa, totemo oishii."},{"jp":"彼は若いにしては、とても落ち着いている。","en":"Considering he is young, he is very calm.","romaji":"Kare wa wakai ni shite wa, totemo ochitsuite iru."},{"jp":"あの人は外国人にしては、日本語がうまい。","en":"For a foreigner, that person is good at Japanese.","romaji":"Ano hito wa gaikokujin ni shite wa, nihongo ga umai."}],"example":"彼女は初心者にしては、上手に水泳ができる。","exampleMeaning":"Considering she is a beginner, she can swim well."},{"pattern":"～にしても (〜ni shitemo)","meaning":"Expresses 'even if', 'no matter', 'regardless of'.","formation":"Verb-casual + にしても, い-Adjective + にしても, な-Adjective + だにしても, Noun + だにしても","examples":[{"jp":"雨が降るにしても、学校へ行かなければなりません。","en":"Even if it rains, I have to go to school.","romaji":"Ame ga furu ni shitemo, gakkou e ikanakereba narimasen."},{"jp":"彼女が怒っているにしても、話し合いは避けられない。","en":"Even if she is angry, we can't avoid talking.","romaji":"Kanojo ga okotte iru ni shitemo, hanashiai wa sakerarenai."},{"jp":"このレストランが高いにしても、料理の質がよくておすすめです。","en":"Even if this restaurant is expensive, I recommend it because the quality of the food is good.","romaji":"Kono resutoran ga takai ni shitemo, ryouri no shitsu ga yokute osusume desu."},{"jp":"彼が有名だにしても、彼の私生活について話すのは失礼だ。","en":"Even if he is famous, it's rude to talk about his private life.","romaji":"Kare ga yuumei da ni shitemo, kare no shiseikatsu ni tsuite hanasu no wa shitsurei da."}],"example":"雨が降るにしても、学校へ行かなければなりません。","exampleMeaning":"Even if it rains, I have to go to school."},{"pattern":"～について (〜ni tsuite)","meaning":"Expressing 'about', 'concerning', or 'regarding'.","formation":"Noun + について","examples":[{"jp":"日本の文化について学びたいです。","en":"I want to learn about Japanese culture.","romaji":"Nihon no bunka ni tsuite manabitai desu."},{"jp":"彼の意見について話し合いましょう。","en":"Let's discuss his opinion.","romaji":"Kare no iken ni tsuite hanashiaimashou."},{"jp":"この問題について詳しく教えてください。","en":"Please explain this issue in detail.","romaji":"Kono mondai ni tsuite kuwashiku oshiete kudasai."},{"jp":"子供たちの教育について考えなければなりません。","en":"We have to think about the children's education.","romaji":"Kodomo-tachi no kyouiku ni tsuite kangaenakereba narimasen."}],"example":"日本の文化について学びたいです。","exampleMeaning":"I want to learn about Japanese culture."},{"pattern":"～にとって (〜ni totte)","meaning":"Express the meaning 'for', 'to', 'from the perspective of'.","formation":"Noun (person or thing) + にとって + Verb/Adjective/Noun","examples":[{"jp":"私にとって、健康は一番大切なことです。","en":"For me, health is the most important thing.","romaji":"Watashi ni totte, kenkou wa ichiban taisetsu na koto desu."},{"jp":"あの会社にとって、このプロジェクトは重要な意味があります。","en":"For that company, this project has significant meaning.","romaji":"Ano kaisha ni totte, kono purojekuto wa juuyou na imi ga arimasu."},{"jp":"子供たちにとって、おもちゃは楽しいものです。","en":"For children, toys are fun things.","romaji":"Kodomotachi ni totte, omocha wa tanoshii mono desu."},{"jp":"外国人にとって、日本語は難しい言語の一つです。","en":"For foreigners, Japanese is one of the difficult languages.","romaji":"Gaikokujin ni totte, nihongo wa muzukashii gengo no hitotsu desu."}],"example":"私にとって、健康は一番大切なことです。","exampleMeaning":"For me, health is the most important thing."},{"pattern":"～によって (〜ni yotte)","meaning":"Indicates the reason or cause, difference depending on a factor, or methods used.","formation":"Verb-casual + によって, い-Adjective + によって, な-Adjective + によって, Noun + によって","examples":[{"jp":"その事故は悪天候によって引き起こされた。","en":"The accident was caused by bad weather.","romaji":"Sono jiko wa akutenkou ni yotte hikiokosareta."},{"jp":"生活習慣によって、健康状態が変わります。","en":"Health conditions change depending on lifestyle habits.","romaji":"Seikatsu shuukan ni yotte, kenkou joutai ga kawarimasu."},{"jp":"彼の成功は努力によって得られたものだ。","en":"His success was achieved through hard work.","romaji":"Kare no seikou wa doryoku ni yotte erareta mono da."},{"jp":"結果は試験の難易度によって異なります。","en":"The results vary depending on the difficulty of the exam.","romaji":"Kekka wa shiken no nan'ido ni yotte kotonarimasu."}],"example":"その事故は悪天候によって引き起こされた。","exampleMeaning":"The accident was caused by bad weather."},{"pattern":"～によれば (〜ni yoreba)","meaning":"Means 'according to', 'based on' or 'by'.","formation":"Noun + によれば","examples":[{"jp":"天気予報によれば、明日は晴れるでしょう。","en":"According to the weather forecast, it will be sunny tomorrow.","romaji":"Tenki yohou ni yoreba, ashita wa hareru deshou."},{"jp":"先生によれば、この問題は簡単だそうです。","en":"According to the teacher, this problem seems to be easy.","romaji":"Sensei ni yoreba, kono mondai wa kantan da sou desu."},{"jp":"調査によれば、若者の喫煙率が減っているということです。","en":"According to the survey, the smoking rate among young people is decreasing.","romaji":"Chousa ni yoreba, wakamono no kitsuenritsu ga hette iru to iu koto desu."},{"jp":"新聞記事によれば、その企業は倒産の危機にあるらしい。","en":"According to the newspaper article, the company appears to be on the verge of bankruptcy.","romaji":"Shinbun kiji ni yoreba, sono kigyou wa tousan no kiki ni aru rashii."}],"example":"天気予報によれば、明日は晴れるでしょう。","exampleMeaning":"According to the weather forecast, it will be sunny tomorrow."},{"pattern":"～に対して","meaning":"Indicates a target or contrast; 'toward', 'against', 'in contrast to', 'in response to'.","formation":"Verb-casual + に対して, い-Adjective + に対して, な-Adjective + に対して, Noun + に対して","examples":[{"jp":"子供たちに対して、親は常にやさしくあるべきです。","en":"Parents should always be kind towards their children.","romaji":"Kodomotachi ni taishite, oya wa tsune ni yasashiku aru beki desu."},{"jp":"彼は質問に対して正直に答えました。","en":"He answered the questions honestly.","romaji":"Kare wa shitsumon ni taishite shoujiki ni kotaemashita."},{"jp":"田中さんは成功したに対して、佐藤さんは失敗しました。","en":"In contrast to Tanaka-san's success, Satou-san failed.","romaji":"Tanaka-san wa seikou shita ni taishite, Satou-san wa shippai shimashita."},{"jp":"彼の意見に対して、私は反対の立場を取りました。","en":"In response to his opinion, I took an opposing stance.","romaji":"Kare no iken ni taishite, watashi wa hantai no tachiba wo torimashita."}],"example":"子供たちに対して、親は常にやさしくあるべきです。","exampleMeaning":"Parents should always be kind towards their children."},{"pattern":"～に比べて (〜ni kurabete)","meaning":"Comparing to; in comparison with; as opposed to.","formation":"Verb-casual + に比べて, い-Adjective + に比べて, な-Adjective + だ/である + に比べて, Noun + だ/である + に比べて","examples":[{"jp":"夏に比べて、冬は寒いです。","en":"Winter is cold compared to summer.","romaji":"Natsu ni kurabete, fuyu wa samui desu."},{"jp":"このトマトは赤いトマトに比べて美味しくない。","en":"This tomato is not as delicious compared to the red tomatoes.","romaji":"Kono tomato wa akai tomato ni kurabete oishikunai."},{"jp":"彼は私に比べて英語が上手です。","en":"He is better at English compared to me.","romaji":"Kare wa watashi ni kurabete eigo ga jouzu desu."},{"jp":"東京に比べて、京都は静かな町です。","en":"Kyoto is a quieter city compared to Tokyo.","romaji":"Toukyou ni kurabete, Kyouto wa shizukana machi desu."}],"example":"夏に比べて、冬は寒いです。","exampleMeaning":"Winter is cold compared to summer."},{"pattern":"～に関して (〜ni kanshite)","meaning":"Regarding, concerning, about, with respect to.","formation":"Noun + に関して","examples":[{"jp":"健康に関して気を付けることが大切です。","en":"It is important to be careful regarding health.","romaji":"Kenkou ni kanshite ki wo tsukeru koto ga taisetsu desu."},{"jp":"このプロジェクトに関しては、彼がすべての詳細を知っています。","en":"Regarding this project, he knows all the details.","romaji":"Kono purojekuto ni kanshite wa, kare ga subete no shousai wo shitteimasu."},{"jp":"環境問題に関して、私たちはもっと責任を持たなければなりません。","en":"Concerning environmental issues, we must take more responsibility.","romaji":"Kankyou mondai ni kanshite, watashitachi wa motto sekinin wo motanakereba narimasen."},{"jp":"この事件に関しての情報はまだ十分ではありません。","en":"The information regarding this incident is still insufficient.","romaji":"Kono jiken ni kanshite no jouhou wa mada juubun de wa arimasen."}],"example":"健康に関して気を付けることが大切です。","exampleMeaning":"It is important to be careful regarding health."},{"pattern":"～の～ (〜no 〜)","meaning":"Indicates possession, attribution, or connection between two nouns.","formation":"Noun1 + の + Noun2","examples":[{"jp":"これは私の傘です。","en":"This is my umbrella.","romaji":"Kore wa watashi no kasa desu."},{"jp":"あのビルは東京の有名な観光スポットです。","en":"That building is a famous tourist spot in Tokyo.","romaji":"Ano biru wa Toukyou no yuumei na kankou supotto desu."},{"jp":"彼は部長の秘書です。","en":"He is the chief's secretary.","romaji":"Kare wa buchou no hisho desu."},{"jp":"彼女は音楽の先生です。","en":"She is a music teacher.","romaji":"Kanojo wa ongaku no sensei desu."}],"example":"これは私の傘です。","exampleMeaning":"This is my umbrella."},{"pattern":"～ばかり (〜bakari)","meaning":"Expresses 'only', 'nothing but', 'always', 'just'.","formation":"Verb-ますstem + ばかり, い-Adjective + ばかり, な-Adjective + ばかり, Noun + ばかり","examples":[{"jp":"彼はゲームばかりしている。","en":"He is always playing games.","romaji":"Kare wa geemu bakari shite iru."},{"jp":"この部屋は綺麗なものばかりだ。","en":"This room has nothing but clean things.","romaji":"Kono heya wa kirei na mono bakari da."},{"jp":"彼女は勉強ばかりしていて、遊んでいる暇がない。","en":"She is always studying and has no time to play.","romaji":"Kanojo wa benkyou bakari shite ite, asonde iru hima ga nai."},{"jp":"彼の話は嘘ばかりで、信じることができない。","en":"His words are nothing but lies, and I cannot believe them.","romaji":"Kare no hanashi wa uso bakari de, shinjiru koto ga dekinai."}],"example":"彼はゲームばかりしている。","exampleMeaning":"He is always playing games."},{"pattern":"～ばかりか (〜bakarika) ～も","meaning":"Not only... but also; more than just; not just","formation":"Verb-casual + ばかりか/も, い-Adjective + ばかりか/も, な-Adjective + だ + ばかりか/も, Noun + だ + ばかりか/も","examples":[{"jp":"彼女は英語ばかりか、フランス語も話せます。","en":"Not only can she speak English, but she can also speak French.","romaji":"Kanojo wa eigo bakarika, furansugo mo hanasemasu."},{"jp":"このレストランは味が良いばかりか、サービスも素晴らしい。","en":"Not only does this restaurant have great taste, but the service is also wonderful.","romaji":"Kono resutoran wa aji ga yoi bakarika, saabisu mo subarashii."},{"jp":"パーティは楽しかったばかりか、料理も美味しかった。","en":"Not only was the party fun, but the food was also delicious.","romaji":"Paatii wa tanoshikatta bakarika, ryouri mo oishikatta."},{"jp":"彼は頭がいいばかりか、スポーツも得意だ。","en":"Not only is he smart, but he is also good at sports.","romaji":"Kare wa atama ga ii bakarika, supootsu mo tokui da."}],"example":"彼女は英語ばかりか、フランス語も話せます。","exampleMeaning":"Not only can she speak English, but she can also speak French."},{"pattern":"～はずだ (〜hazu da)","meaning":"Expresses an expectation, 'should' or 'it is supposed to'.","formation":"Verb-casual + はずだ, い-Adjective + はずだ, な-Adjective + なはずだ, Noun + のはずだ","examples":[{"jp":"彼はもう着いたはずだ。","en":"He should have arrived by now.","romaji":"Kare wa mou tsuita hazu da."},{"jp":"この薬を飲むと、痛みがなくなるはずだ。","en":"If you take this medicine, the pain should go away.","romaji":"Kono kusuri wo nomu to, itami ga nakunaru hazu da."},{"jp":"明日は晴れるはずだ。","en":"It is supposed to be sunny tomorrow.","romaji":"Ashita wa hareru hazu da."},{"jp":"彼女は元気なはずだ。","en":"She is supposed to be well.","romaji":"Kanojo wa genki na hazu da."}],"example":"彼はもう着いたはずだ。","exampleMeaning":"He should have arrived by now."},{"pattern":"～ば～のに (〜ba 〜noni)","meaning":"Expresses regret or dissatisfaction; 'if only', 'wish'.","formation":"Verb-ば form + ～のに, い-Adjective-ば form + ～のに, な-Adjective + であれば + ～のに, Noun + であれば + ～のに","examples":[{"jp":"もっと早く来れば、電車に間に合ったのに。","en":"If only I had come earlier, I would have made it to the train.","romaji":"Motto hayaku kureba, densha ni maniatta noni."},{"jp":"もっと勉強すれば、試験に合格したのに。","en":"I wish I had studied more, I would have passed the exam.","romaji":"Motto benkyou sureba, shiken ni goukaku shita noni."},{"jp":"彼女がもっと優しければ、彼と上手くいくのに。","en":"If only she were kinder, she would get along with him.","romaji":"Kanojo ga motto yasashikereba, kare to umaku iku noni."},{"jp":"日本語が上手であれば、この本が読めるのに。","en":"I wish I were good at Japanese, then I could read this book.","romaji":"Nihongo ga jouzu de areba, kono hon ga yomeru noni."}],"example":"もっと早く来れば、電車に間に合ったのに。","exampleMeaning":"If only I had come earlier, I would have made it to the train."},{"pattern":"～ば～ほど (〜ba 〜hodo)","meaning":"Expresses 'the more ~, the more ~'; a proportional relationship between two phrases.","formation":"Verb-casual + ば + Verb-casual + ほど, い-Adjective + ば + い-Adjective + ほど, な-Adjective + であれば + な-Adjective + ほど","examples":[{"jp":"早く起きれば起きるほど、時間がたくさんある。","en":"The earlier you wake up, the more time you have.","romaji":"Hayaku okireba okiru hodo, jikan ga takusan aru."},{"jp":"練習すればするほど、上達します。","en":"The more you practice, the more you will improve.","romaji":"Renshuu sureba suru hodo, joutatsu shimasu."},{"jp":"料理が美味しければ美味しいほど、皆が喜びます。","en":"The more delicious the food is, the happier everyone will be.","romaji":"Ryouri ga oishikereba oishii hodo, mina ga yorokobimasu."},{"jp":"日本語が上手であれば上手なほど、日本の生活が楽になります。","en":"The better your Japanese is, the easier life in Japan will be.","romaji":"Nihongo ga jouzu de areba jouzu na hodo, Nihon no seikatsu ga raku ni narimasu."}],"example":"早く起きれば起きるほど、時間がたくさんある。","exampleMeaning":"The earlier you wake up, the more time you have."},{"pattern":"～はもちろん～も (〜wa mochiron 〜mo)","meaning":"Used for emphasizing that not only one thing but also another thing is included. It means 'not only... but also' or 'of course... and...'.","formation":"Noun1 + はもちろん + Noun2 + も","examples":[{"jp":"彼は数学はもちろん、英語も得意です。","en":"Not only is he good at math, but he is also good at English.","romaji":"Kare wa suugaku wa mochiron, eigo mo tokui desu."},{"jp":"このレストランは和食はもちろん、洋食も美味しいです。","en":"This restaurant not only has delicious Japanese food but also delicious Western food.","romaji":"Kono resutoran wa washoku wa mochiron, youshoku mo oishii desu."},{"jp":"私の趣味は音楽はもちろん、読書も大好きです。","en":"My hobbies are not only listening to music, but I also love reading.","romaji":"Watashi no shumi wa ongaku wa mochiron, dokusho mo daisuki desu."},{"jp":"東京は観光はもちろん、ビジネスも盛んです。","en":"Tokyo is not only famous for sightseeing but also has a thriving business scene.","romaji":"Toukyou wa kankou wa mochiron, bijinesu mo sakan desu."}],"example":"彼は数学はもちろん、英語も得意です。","exampleMeaning":"Not only is he good at math, but he is also good at English."},{"pattern":"～ばよかった (〜ba yokatta)","meaning":"Express a sense of regret; 'I wish', 'it would have been better if'.","formation":"Verb-ば-form + よかった, い-Adjective-く + ばよかった, な-Adjective + ならよかった","examples":[{"jp":"もっと早く起きればよかった。","en":"I wish I had woken up earlier.","romaji":"Motto hayaku okireba yokatta."},{"jp":"昨日のパーティーに行けばよかった。","en":"I wish I had gone to yesterday's party.","romaji":"Kinou no paatii ni ikeba yokatta."},{"jp":"もっと安いものを買えばよかった。","en":"I wish I had bought something cheaper.","romaji":"Motto yasui mono wo kaeba yokatta."},{"jp":"あの時、もっと勉強すればよかった。","en":"I wish I had studied more at that time.","romaji":"Ano toki, motto benkyou sureba yokatta."}],"example":"もっと早く起きればよかった。","exampleMeaning":"I wish I had woken up earlier."},{"pattern":"～ふりをする (〜furi wo suru)","meaning":"Pretending or acting as if; 'pretend', 'act like'.","formation":"Verb (dictionary form) + ふりをする, い-Adjective + ふりをする, な-Adjective + ふりをする, Noun + ふりをする","examples":[{"jp":"彼は知らないふりをしました。","en":"He pretended not to know.","romaji":"Kare wa shiranai furi wo shimashita."},{"jp":"彼女は病気のふりをして、学校を休みました。","en":"She pretended to be sick and skipped school.","romaji":"Kanojo wa byouki no furi wo shite, gakkou wo yasumimashita."},{"jp":"彼は嬉しいふりをしていますが、本当は悲しいです。","en":"He is pretending to be happy, but he is actually sad.","romaji":"Kare wa ureshii furi wo shiteimasu ga, hontou wa kanashii desu."},{"jp":"彼女はリーダーのふりをして、チームを率いました。","en":"She pretended to be a leader and led the team.","romaji":"Kanojo wa riidaa no furi wo shite, chiimu wo hikimashita."}],"example":"彼は知らないふりをしました。","exampleMeaning":"He pretended not to know."},{"pattern":"～べきだ (〜beki da)","meaning":"Express an obligation or something that should be done (mainly with verbs).","formation":"Verb-dictionary form + べきだ","examples":[{"jp":"勉強するべきだ。","en":"You should study.","romaji":"Benkyou suru beki da."},{"jp":"早く寝るべきだ。","en":"You should sleep early.","romaji":"Hayaku neru beki da."},{"jp":"静かにするべきだ。","en":"You should be quiet.","romaji":"Shizuka ni suru beki da."},{"jp":"彼に謝るべきだ。","en":"You should apologize to him.","romaji":"Kare ni ayamaru beki da."}],"example":"勉強するべきだ。","exampleMeaning":"You should study."},{"pattern":"～ほど～ (〜hodo〜)","meaning":"Expresses the degree or extent; 'about', 'to the extent', 'as much as'.","formation":"Verb-casual + ほど, い-Adjective + ほど, な-Adjective + ほど, Noun + ほど","examples":[{"jp":"彼女は私ほど速く走ることができません。","en":"She cannot run as fast as me.","romaji":"Kanojo wa watashi hodo hayaku hashiru koto ga dekimasen."},{"jp":"このケーキはあのケーキほど美味しくない。","en":"This cake is not as delicious as that cake.","romaji":"Kono keeki wa ano keeki hodo oishikunai."},{"jp":"日本ほど四季がはっきりしている国はない。","en":"There is no country with as distinct seasons as Japan.","romaji":"Nihon hodo shiki ga hakkiri shite iru kuni wa nai."},{"jp":"東京は大阪ほど人が多くない。","en":"Tokyo does not have as many people as Osaka.","romaji":"Toukyou wa Oosaka hodo hito ga ookunai."}],"example":"彼女は私ほど速く走ることができません。","exampleMeaning":"She cannot run as fast as me."},{"pattern":"～ますように (〜masu you ni)","meaning":"Used to express a wish or hope for oneself or someone else.","formation":"Verb-ます form, remove final る + ように","examples":[{"jp":"明日のテストで良い点をとりますように。","en":"I hope I get good grades on tomorrow's test.","romaji":"Ashita no tesuto de ii ten wo torimasu you ni."},{"jp":"彼が無事に帰ってきますように。","en":"I hope he comes back safely.","romaji":"Kare ga buji ni kaette kimasu you ni."},{"jp":"みんなが健康でいられますように。","en":"I hope everyone stays healthy.","romaji":"Minna ga kenkou de iraremasu you ni."},{"jp":"彼女に幸せになりますように。","en":"I hope she becomes happy.","romaji":"Kanojo ni shiawase ni narimasu you ni."}],"example":"明日のテストで良い点をとりますように。","exampleMeaning":"I hope I get good grades on tomorrow's test."},{"pattern":"まったく～ない","meaning":"Completely not; not at all.","formation":"まったく + Verb-negative, まったく + い-Adjective-negative, まったく + な-Adjective-negative","examples":[{"jp":"彼は、まったく覚えていない。","en":"He doesn't remember at all.","romaji":"Kare wa, mattaku oboete inai."},{"jp":"この部屋はまったく暖かくない。","en":"This room is not warm at all.","romaji":"Kono heya wa mattaku atatakakunai."},{"jp":"彼女はまったく遅れていない。","en":"She is not late at all.","romaji":"Kanojo wa mattaku okurete inai."},{"jp":"これはまったく便利ではない。","en":"This is not convenient at all.","romaji":"Kore wa mattaku benri de wa nai."}],"example":"彼は、まったく覚えていない。","exampleMeaning":"He doesn't remember at all."},{"pattern":"～まで (〜made)","meaning":"Express 'until', 'up to', or 'as far as' to indicate the end point of an action or range.","formation":"Verb-casual + まで, い-Adjective + まで, な-Adjective + まで, Noun + まで","examples":[{"jp":"10時まで働きます。","en":"I will work until 10 o'clock.","romaji":"Ju-ji made hatarakimasu."},{"jp":"東京まで電車で行きます。","en":"I will go by train as far as Tokyo.","romaji":"Toukyou made densha de ikimasu."},{"jp":"彼は疲れるまで走りました。","en":"He ran until he got tired.","romaji":"Kare wa tsukareru made hashirimashita."},{"jp":"5ページまで読んでください。","en":"Please read up to page 5.","romaji":"Go-peeji made yonde kudasai."}],"example":"10時まで働きます。","exampleMeaning":"I will work until 10 o'clock."},{"pattern":"～まま (〜mama)","meaning":"Expresses the state or condition remaining unchanged.","formation":"Verb-ます stem + まま, い-Adjective + まま, な-Adjective + なまま, Noun + のまま","examples":[{"jp":"部屋の窓を開けたまま寝ました。","en":"I slept with the window of the room open.","romaji":"Heya no mado wo aketa mama nemashita."},{"jp":"熱いままのコーヒーを飲んで、舌を焦がしました。","en":"I drank the coffee while it was still hot and burned my tongue.","romaji":"Atsui mama no koohii wo nonde, shita wo kogashimashita."},{"jp":"彼は忙しいなまま、休みの日も仕事をしています。","en":"He continues to be busy, working even on his days off.","romaji":"Kare wa isogashii na mama, yasumi no hi mo shigoto wo shiteimasu."},{"jp":"彼女は故郷にいるまま、外国に行かないで仕事を見つけた。","en":"She found a job without going abroad, staying in her hometown.","romaji":"Kanojo wa furusato ni iru mama, gaikoku ni ikanaide shigoto wo mitsuketa."}],"example":"部屋の窓を開けたまま寝ました。","exampleMeaning":"I slept with the window of the room open."},{"pattern":"まるで～よう","meaning":"Used to express a strong resemblance or similarity; 'as if', 'just like', 'as though'.","formation":"まるで + phrase/sentence + よう","examples":[{"jp":"彼女はまるで天使のように美しい。","en":"She is as beautiful as an angel.","romaji":"Kanojo wa maru de tenshi no you ni utsukushii."},{"jp":"彼はまるでロボットのように仕事をしている。","en":"He works as if he is a robot.","romaji":"Kare wa maru de robotto no you ni shigoto wo shite iru."},{"jp":"あの家はまるでお城のようだ。","en":"That house is just like a castle.","romaji":"Ano ie wa maru de oshiro no you da."},{"jp":"ここはまるで楽園のような場所です。","en":"This place is as though it's a paradise.","romaji":"Koko wa maru de rakuen no you na basho desu."}],"example":"彼女はまるで天使のように美しい。","exampleMeaning":"She is as beautiful as an angel."},{"pattern":"～てみる (〜te miru)","meaning":"A grammar structure used to express the action of trying or attempting something to see what happens.","formation":"Verb-て form + みる","examples":[{"jp":"彼は走ってみたが、まだ膝が痛いと感じた。","en":"He tried running, but he still felt pain in his knee.","romaji":"Kare wa hashitte mita ga, mada hiza ga itai to kanjita."},{"jp":"彼女は料理を作ってみたが、失敗してしまった。","en":"She tried cooking but ended up failing.","romaji":"Kanojo wa ryouri o tsukutte mita ga, shippai shite shimatta."},{"jp":"初めてのデートで、彼は彼女にサプライズをしようと考え、歌ってみた。","en":"On their first date, he thought of surprising her and tried singing.","romaji":"Hajimete no deeto de, kare wa kanojo ni sapuraizu o shiyou to kangae, utatte mita."},{"jp":"このケーキは美味しそうだから、味見に食べてみる。","en":"Since this cake looks delicious, I will try tasting it.","romaji":"Kono keeki wa oishisou dakara, ajimi ni tabete miru."}],"example":"彼は走ってみたが、まだ膝が痛いと感じた。","exampleMeaning":"He tried running, but he still felt pain in his knee."},{"pattern":"～みたいだ (〜mitai da)","meaning":"Express similarity or appearance; 'like', 'seems', 'looks'.","formation":"Verb-casual + みたいだ, い-Adjective + みたいだ, な-Adjective + みたいだ, Noun + みたいだ","examples":[{"jp":"彼は怒っているみたいだ。","en":"He seems to be angry.","romaji":"Kare wa okotte iru mitai da."},{"jp":"そのビルは古いみたいだ。","en":"That building looks old.","romaji":"Sono biru wa furui mitai da."},{"jp":"彼女は疲れているみたいだ。","en":"She seems to be tired.","romaji":"Kanojo wa tsukarete iru mitai da."},{"jp":"この料理は辛いみたいだ。","en":"This dish seems to be spicy.","romaji":"Kono ryouri wa karai mitai da."}],"example":"彼は怒っているみたいだ。","exampleMeaning":"He seems to be angry."},{"pattern":"～めったに～ない (〜metta ni 〜nai)","meaning":"Used to express that something rarely, hardly ever or seldom happens.","formation":"めったに + Verb[ない-form] / めったに + い-Adjective[ない-form] / めったに + な-Adjective[じゃない/ではない-form]","examples":[{"jp":"彼はめったに外食しない。","en":"He hardly ever eats out.","romaji":"Kare wa metta ni gaishoku shinai."},{"jp":"私はめったに寿司を食べない。","en":"I seldom eat sushi.","romaji":"Watashi wa metta ni sushi wo tabenai."},{"jp":"この地域はめったに雪が降らない。","en":"It hardly ever snows in this area.","romaji":"Kono chiiki wa metta ni yuki ga furanai."},{"jp":"彼女はめったに怒らない。","en":"She hardly ever gets angry.","romaji":"Kanojo wa metta ni okoranai."}],"example":"彼はめったに外食しない。","exampleMeaning":"He hardly ever eats out."},{"pattern":"～めったにない (〜metta ni nai)","meaning":"Expresses the rarity of an action, event or state; 'hardly', 'rarely', 'seldom'.","formation":"Verb-negative + めったにない, い-Adjective-negative + めったにない, な-Adjective-negative + めったにない, Noun-negative + めったにない","examples":[{"jp":"この町では雪が降ることはめったにない。","en":"It hardly ever snows in this town.","romaji":"Kono machi de wa yuki ga furu koto wa metta ni nai."},{"jp":"彼はめったに外食しない。","en":"He rarely eats out.","romaji":"Kare wa metta ni gaishoku shinai."},{"jp":"友達が遊びに来るのはめったにない。","en":"Friends seldom come to visit.","romaji":"Tomodachi ga asobi ni kuru no wa metta ni nai."},{"jp":"彼女はめったに怒らない。","en":"She hardly ever gets angry.","romaji":"Kanojo wa metta ni okoranai."}],"example":"この町では雪が降ることはめったにない。","exampleMeaning":"It hardly ever snows in this town."},{"pattern":"もしかすると〜かもしれない (moshikasuru to 〜kamoshirenai)","meaning":"Express the possibility of something; 'maybe', 'perhaps', 'might'.","formation":"もしかすると + Sentence + かもしれない","examples":[{"jp":"もしかすると彼は遅刻するかもしれない。","en":"Maybe he might be late.","romaji":"Moshikasuru to kare wa chikoku suru kamoshirenai."},{"jp":"もしかすると彼女は疲れているかもしれない。","en":"Perhaps she might be tired.","romaji":"Moshikasuru to kanojo wa tsukarete iru kamoshirenai."},{"jp":"もしかすると雨が降るかもしれない。","en":"It might rain, maybe.","romaji":"Moshikasuru to ame ga furu kamoshirenai."},{"jp":"もしかすると彼らはその映画が好きじゃないかもしれない。","en":"Maybe they might not like that movie.","romaji":"Moshikasuru to karera wa sono eiga ga suki janai kamoshirenai."}],"example":"もしかすると彼は遅刻するかもしれない。","exampleMeaning":"Maybe he might be late."},{"pattern":"もし～たなら","meaning":"Express a hypothetical condition, 'if' or 'in case'.","formation":"もし + Verb-casual past + なら, もし + い-Adjective-casual past + なら, もし + な-Adjective + だったなら, もし + Noun + だったなら","examples":[{"jp":"もし雨が降ったなら、傘を持って行きましょう。","en":"If it rains, let's bring an umbrella.","romaji":"Moshi ame ga futta nara, kasa wo motte ikimashou."},{"jp":"もしケーキが美味しくなかったなら、誰も食べないでしょう。","en":"If the cake was not delicious, nobody would eat it.","romaji":"Moshi keeki ga oishikunakatta nara, daremo tabenai deshou."},{"jp":"もし彼が病気だったなら、すぐに病院に行かせてあげてください。","en":"If he was sick, please take him to the hospital right away.","romaji":"Moshi kare ga byouki datta nara, sugu ni byouin ni ikasete agete kudasai."},{"jp":"もし彼女が学生だったなら、このレストランは割引があるでしょう。","en":"If she were a student, there would be a discount at this restaurant.","romaji":"Moshi kanojo ga gakusei datta nara, kono resutoran wa waribiki ga aru deshou."}],"example":"もし雨が降ったなら、傘を持って行きましょう。","exampleMeaning":"If it rains, let's bring an umbrella."},{"pattern":"もし～ても","meaning":"Express a hypothetical situation or assumption with the nuance of 'even if'.","formation":"もし + Verb-て form + も / もし + い-Adjective(く) + ても / もし + な-Adjective/Noun + でも","examples":[{"jp":"もし雨が降っても、ピクニックに行きます。","en":"Even if it rains, we will go on a picnic.","romaji":"Moshi ame ga futtemo, pikunikku ni ikimasu."},{"jp":"もし彼が謝っても、まだ怒っているでしょう。","en":"Even if he apologizes, I will still be angry.","romaji":"Moshi kare ga ayamattemo, mada okotteiru deshou."},{"jp":"もし試験に合格しても、まだ勉強を続けます。","en":"Even if I pass the exam, I will still continue studying.","romaji":"Moshi shiken ni goukaku shitemo, mada benkyou wo tsuzukemasu."},{"jp":"もし彼女が遅く来ても、待っています。","en":"Even if she comes late, I will wait.","romaji":"Moshi kanojo ga osoku kite mo, matteimasu."}],"example":"もし雨が降っても、ピクニックに行きます。","exampleMeaning":"Even if it rains, we will go on a picnic."},{"pattern":"もしも～なら","meaning":"Express a hypothetical condition or situation; 'if', 'in case', 'suppose'.","formation":"Verb-casual + なら, い-Adjective + なら, な-Adjective + なら, Noun + なら","examples":[{"jp":"もしも明日雨が降ったなら、出かけません。","en":"If it rains tomorrow, I won't go out.","romaji":"Moshimo ashita ame ga futta nara, dekakemasen."},{"jp":"もしも彼が来なかったなら、私たちだけでパーティーをします。","en":"If he doesn't come, we'll have the party just by ourselves.","romaji":"Moshimo kare ga konakatta nara, watashitachi dake de paatii wo shimasu."},{"jp":"もしも彼女が疲れているなら、休ませてあげてください。","en":"If she is tired, please let her rest.","romaji":"Moshimo kanojo ga tsukarete iru nara, yasumasete agete kudasai."},{"jp":"もしもそれが真実なら、認めなければなりません。","en":"If that is true, we have to admit it.","romaji":"Moshimo sore ga shinjitsu nara, mitomenakereba narimasen."}],"example":"もしも明日雨が降ったなら、出かけません。","exampleMeaning":"If it rains tomorrow, I won't go out."},{"pattern":"～ようとしない (〜you to shinai)","meaning":"Not showing any sign or intention to do something.","formation":"Verb-volitional form + としない","examples":[{"jp":"彼は勉強しようとしない。","en":"He doesn't show any sign of trying to study.","romaji":"Kare wa benkyou shiyou to shinai."},{"jp":"彼女は謝ろうとしない。","en":"She doesn't show any intention of apologizing.","romaji":"Kanojo wa ayamarou to shinai."},{"jp":"息子は部屋を片付けようとしない。","en":"My son doesn't show any intention of cleaning his room.","romaji":"Musuko wa heya wo katazuke you to shinai."},{"jp":"犬は散歩に行こうとしない。","en":"The dog doesn't show any sign of wanting to go for a walk.","romaji":"Inu wa sanpo ni ikou to shinai."}],"example":"彼は勉強しようとしない。","exampleMeaning":"He doesn't show any sign of trying to study."},{"pattern":"～ようと思う (〜you to omou)","meaning":"Expresses the speaker's intention or plan to do something.","formation":"Verb-volitional + と思う","examples":[{"jp":"今日は早く寝ようと思います。","en":"I think I will go to bed early today.","romaji":"Kyou wa hayaku neyou to omoimasu."},{"jp":"明日美術館に行こうと思っています。","en":"I am planning to go to the art museum tomorrow.","romaji":"Ashita bijutsukan ni ikou to omotteimasu."},{"jp":"新しいカメラを買おうと思います。","en":"I think I will buy a new camera.","romaji":"Atarashii kamera wo kaou to omoimasu."},{"jp":"来週友達と映画を見ようと思っています。","en":"I am planning to watch a movie with my friend next week.","romaji":"Raishuu tomodachi to eiga wo miyou to omotteimasu."}],"example":"今日は早く寝ようと思います。","exampleMeaning":"I think I will go to bed early today."},{"pattern":"～ように (〜you ni)","meaning":"Expressing a purpose, a goal or a way of doing something; 'in order to', 'so that', 'like', 'as'","formation":"Verb-casual + ように, い-Adjective + ように, な-Adjective + に, Noun + のように","examples":[{"jp":"早く家に帰るように、仕事を急いで終わらせました。","en":"In order to get home early, I hurried to finish my work.","romaji":"Hayaku ie ni kaeru you ni, shigoto wo isoide owarasemashita."},{"jp":"彼女は美しい花のように見えました。","en":"She looked like a beautiful flower.","romaji":"Kanojo wa utsukushii hana no you ni miemashita."},{"jp":"この部屋がきれいになるように、掃除をしましょう。","en":"Let's clean so that this room becomes clean.","romaji":"Kono heya ga kirei ni naru you ni, souji wo shimashou."},{"jp":"山田さんは元気なように振る舞っていましたが、実際は疲れているらしいです。","en":"Yamada-san was acting as if he was energetic, but he actually seems to be tired.","romaji":"Yamada-san wa genki na you ni furumatte imashita ga, jissai wa tsukarete iru rashii desu."}],"example":"早く家に帰るように、仕事を急いで終わらせました。","exampleMeaning":"In order to get home early, I hurried to finish my work."},{"pattern":"～ように (〜you ni)","meaning":"Used to express a purpose, a way, or a natural tendency.","formation":"Verb-casual + ように, い-Adjective + ように, な-Adjective + だように, Noun + のように","examples":[{"jp":"子供が安全に過ごせるように、家の中を整理します。","en":"I will organize the inside of the house so that the children can spend time safely.","romaji":"Kodomo ga anzen ni sugoseru you ni, ie no naka wo seiri shimasu."},{"jp":"美しい花のように、彼女は笑顔が素敵です。","en":"Like a beautiful flower, her smile is lovely.","romaji":"Utsukushii hana no you ni, kanojo wa egao ga suteki desu."},{"jp":"自然に英語を話せるように、毎日練習しています。","en":"I practice every day to be able to speak English naturally.","romaji":"Shizen ni eigo wo hanaseru you ni, mainichi renshuu shiteimasu."},{"jp":"成功するように、計画を立てましょう。","en":"Let's make a plan to succeed.","romaji":"Seikou suru you ni, keikaku wo tatemashou."}],"example":"子供が安全に過ごせるように、家の中を整理します。","exampleMeaning":"I will organize the inside of the house so that the children can spend time safely."},{"pattern":"～ように (〜you ni)","meaning":"Used to express purpose or how something is done; 'like', 'as if', 'in order to'.","formation":"Verb-casual + ように, い-Adjective + ように, な-Adjective + に, Noun + のように","examples":[{"jp":"分かりやすいように説明してください。","en":"Please explain it in a way that is easy to understand.","romaji":"Wakariyasui you ni setsumei shite kudasai."},{"jp":"彼は鳥のように歌います。","en":"He sings like a bird.","romaji":"Kare wa tori no you ni utaimasu."},{"jp":"友達と仲良くするように努めています。","en":"I am trying to get along well with my friends.","romaji":"Tomodachi to nakayoku suru you ni tsutometeimasu."},{"jp":"日本語が上手になるように勉強しています。","en":"I am studying to become better at Japanese.","romaji":"Nihongo ga jouzu ni naru you ni benkyou shiteimasu."}],"example":"分かりやすいように説明してください。","exampleMeaning":"Please explain it in a way that is easy to understand."},{"pattern":"～ようにしましょう (〜you ni shimashou)","meaning":"A suggestion to make an effort or try to do something; 'let's try to', 'let's make sure to'.","formation":"Verb-dictionary form + ようにしましょう / Verb-negative form + ようにしましょう","examples":[{"jp":"毎日運動するようにしましょう。","en":"Let's try to exercise every day.","romaji":"Mainichi undou suru you ni shimashou."},{"jp":"早く寝るようにしましょう。","en":"Let's make sure to go to bed early.","romaji":"Hayaku neru you ni shimashou."},{"jp":"親切にするようにしましょう。","en":"Let's try to be kind.","romaji":"Shinsetsu ni suru you ni shimashou."},{"jp":"時間を無駄にしないようにしましょう。","en":"Let's make sure not to waste time.","romaji":"Jikan wo muda ni shinai you ni shimashou."}],"example":"毎日運動するようにしましょう。","exampleMeaning":"Let's try to exercise every day."},{"pattern":"～ようになった (〜you ni natta)","meaning":"Express an event or state that became possible; 'became able to', 'started to', 'now can'.","formation":"Verb-casual + ようになった","examples":[{"jp":"彼は料理を作るようになった。","en":"He became able to cook.","romaji":"Kare wa ryouri wo tsukuru you ni natta."},{"jp":"その子は読めるようになった。","en":"That child started to be able to read.","romaji":"Sono ko wa yomeru you ni natta."},{"jp":"会議は週に一度開催されるようになった。","en":"The meeting started to be held once a week.","romaji":"Kaigi wa shuu ni ichido kaisai sareru you ni natta."},{"jp":"日本語がわかるようになった。","en":"I became able to understand Japanese.","romaji":"Nihongo ga wakaru you ni natta."}],"example":"彼は料理を作るようになった。","exampleMeaning":"He became able to cook."},{"pattern":"～ように言う (〜you ni iu)","meaning":"To convey a message, instruction or request to someone; 'to tell (someone) to', 'to say to (someone)'.","formation":"Verb-dictionary form + ように言う / Verb-nai form + ように言う","examples":[{"jp":"先生は私にもっと勉強するように言った。","en":"The teacher told me to study more.","romaji":"Sensei wa watashi ni motto benkyou suru you ni itta."},{"jp":"彼女は彼に待つように言いました。","en":"She told him to wait.","romaji":"Kanojo wa kare ni matsu you ni iimashita."},{"jp":"母は私に部屋を片付けるように言いました。","en":"My mother told me to clean my room.","romaji":"Haha wa watashi ni heya wo katazukeru you ni iimashita."},{"jp":"先生は生徒に質問をするように言った。","en":"The teacher told the student to ask a question.","romaji":"Sensei wa seito ni shitsumon wo suru you ni itta."}],"example":"先生は私にもっと勉強するように言った。","exampleMeaning":"The teacher told me to study more."},{"pattern":"～らしい (〜rashii)","meaning":"Expresses hearsay; 'I heard', 'it seems', 'apparently'.","formation":"Verb-casual + らしい, い-Adjective + らしい, な-Adjective + だらしい, Noun + だらしい","examples":[{"jp":"彼はインフルエンザらしい。","en":"Apparently, he has the flu.","romaji":"Kare wa infuruenza rashii."},{"jp":"明日雪が降るらしい。","en":"I heard it will snow tomorrow.","romaji":"Ashita yuki ga furu rashii."},{"jp":"このレストランは美味しいらしい。","en":"I heard that this restaurant is delicious.","romaji":"Kono resutoran wa oishii rashii."},{"jp":"彼女は医者だらしい。","en":"It seems that she is a doctor.","romaji":"Kanojo wa isha darashii."}],"example":"彼はインフルエンザらしい。","exampleMeaning":"Apparently, he has the flu."},{"pattern":"～られた (〜rareta)","meaning":"Express a passive action, 'was/were', 'has/have been'.","formation":"Verb (passive form, past tense) + られた","examples":[{"jp":"この本はたくさんの人に読まれた。","en":"This book was read by many people.","romaji":"Kono hon wa takusan no hito ni yomareta."},{"jp":"彼は友達に騙された。","en":"He was deceived by his friend.","romaji":"Kare wa tomodachi ni damasareta."},{"jp":"昨日、私の財布が盗まれました。","en":"Yesterday, my wallet was stolen.","romaji":"Kinou, watashi no saifu ga nusumaremashita."},{"jp":"彼女は映画に感動させられた。","en":"She was deeply moved by the movie.","romaji":"Kanojo wa eiga ni kandou saserareta."}],"example":"この本はたくさんの人に読まれた。","exampleMeaning":"This book was read by many people."},{"pattern":"～ている (〜te iru)","meaning":"Expresses a continuing action or a resulting state; 'is ~ing', 'has been', 'has'.","formation":"Verb-て form + いる","examples":[{"jp":"窓が開けられている。","en":"The window is open (someone opened it and it remains open).","romaji":"Mado ga akerarete iru."},{"jp":"ケーキが全部食べられている。","en":"The whole cake has been eaten.","romaji":"Keeki ga zenbu taberarete iru."},{"jp":"彼女は病気で寝込んでいる。","en":"She is bedridden due to illness.","romaji":"Kanojo wa byouki de nekonde iru."},{"jp":"宿題が終わっている。","en":"The homework is finished (has been done).","romaji":"Shukudai ga owatte iru."}],"example":"窓が開けられている。","exampleMeaning":"The window is open (someone opened it and it remains open)."},{"pattern":"～わけがない (〜wake ga nai)","meaning":"Expresses that something is impossible or unreasonable; 'there's no way', 'can't be'.","formation":"Verb-casual + わけがない, い-Adjective + わけがない, な-Adjective + なわけがない, Noun + のわけがない","examples":[{"jp":"彼がそんなことを言うわけがない。","en":"There's no way he would say something like that.","romaji":"Kare ga sonna koto wo iu wake ga nai."},{"jp":"あのレストランがまずいわけがない。","en":"There's no way that restaurant tastes bad.","romaji":"Ano resutoran ga mazui wake ga nai."},{"jp":"彼女が優しくないわけがない。","en":"There's no way she's not kind.","romaji":"Kanojo ga yasashiku nai wake ga nai."},{"jp":"彼が試験に合格しないわけがない。","en":"There's no way he won't pass the exam.","romaji":"Kare ga shiken ni goukaku shinai wake ga nai."}],"example":"彼がそんなことを言うわけがない。","exampleMeaning":"There's no way he would say something like that."},{"pattern":"～わけだ (〜wake da)","meaning":"Expresses a logical conclusion or reason based on information; 'that's why', 'no wonder', 'it means'.","formation":"Verb-casual + わけだ, い-Adjective + わけだ, な-Adjective + なわけだ, Noun + のわけだ","examples":[{"jp":"彼は風邪を引いている。だから、声がかすれているわけだ。","en":"He has a cold. That's why his voice is hoarse.","romaji":"Kare wa kaze wo hiite iru. Dakara, koe ga kasurete iru wake da."},{"jp":"今日は忙しかった。だから、疲れたわけだ。","en":"Today was busy. No wonder I'm tired.","romaji":"Kyou wa isogashikatta. Dakara, tsukareta wake da."},{"jp":"田中さんはたくさん勉強している。だから、試験に合格したわけだ。","en":"Tanaka has been studying a lot. It means he passed the exam.","romaji":"Tanaka-san wa takusan benkyou shite iru. Dakara, shiken ni goukaku shita wake da."},{"jp":"彼女は有名な歌手の娘なんだ。だから、歌が上手なわけだ。","en":"She's the daughter of a famous singer. That's why she's good at singing.","romaji":"Kanojo wa yuumei na kashu no musume nan da. Dakara, uta ga jouzu na wake da."}],"example":"彼は風邪を引いている。だから、声がかすれているわけだ。","exampleMeaning":"He has a cold. That's why his voice is hoarse."},{"pattern":"～わけではない (〜wake dewa nai)","meaning":"Denies a general assumption; 'it does not mean that', 'it's not the case'.","formation":"Verb-casual + わけではない, い-Adjective + わけではない, な-Adjective + だわけではない, Noun + だわけではない","examples":[{"jp":"彼が忙しいからといって、友達がいないわけではない。","en":"Just because he's busy doesn't mean he has no friends.","romaji":"Kare ga isogashii kara to itte, tomodachi ga inai wake dewa nai."},{"jp":"この映画は面白くないわけではないが、好みではない。","en":"It's not that this movie isn't interesting; it's just not my taste.","romaji":"Kono eiga wa omoshirokunai wake dewa nai ga, konomi dewa nai."},{"jp":"彼女が病気だからといって、毎日寝ているわけではない。","en":"Just because she's sick doesn't mean she's in bed all day.","romaji":"Kanojo ga byouki dakara to itte, mainichi nete iru wake dewa nai."},{"jp":"彼が大学に行っていないからといって、バカだわけではない。","en":"Just because he didn't go to college doesn't mean he's stupid.","romaji":"Kare ga daigaku ni itte inai kara to itte, baka da wake dewa nai."}],"example":"彼が忙しいからといって、友達がいないわけではない。","exampleMeaning":"Just because he's busy doesn't mean he has no friends."},{"pattern":"～わけにはいかない (〜wake ni wa ikanai)","meaning":"Expresses that something cannot be allowed or permitted due to social/moral obligations.","formation":"Verb-casual + わけにはいかない","examples":[{"jp":"こんなところで寝るわけにはいかない。","en":"I can't possibly sleep in a place like this.","romaji":"Konna tokoro de neru wake ni wa ikanai."},{"jp":"試験が明日だから、遊びに行くわけにはいかない。","en":"I can't afford to go out to have fun, since the exam is tomorrow.","romaji":"Shiken ga ashita dakara, asobi ni iku wake ni wa ikanai."},{"jp":"こんなに高いものを買うわけにはいかない。","en":"I can't allow myself to purchase something so expensive.","romaji":"Konna ni takai mono wo kau wake ni wa ikanai."},{"jp":"体調が悪いから、パーティーに参加するわけにはいかない。","en":"Since I'm not feeling well, I can't attend the party.","romaji":"Taichou ga warui kara, paatii ni sanka suru wake ni wa ikanai."}],"example":"こんなところで寝るわけにはいかない。","exampleMeaning":"I can't possibly sleep in a place like this."},{"pattern":"～わりには (〜wari ni wa)","meaning":"Expresses contrast between expectation and reality; 'despite', 'considering', 'even though'.","formation":"Verb-casual + わりには, い-Adjective + わりには, な-Adjective + だわりには, Noun + だわりには","examples":[{"jp":"彼はあまり勉強しないわりには、テストの点数が高いです。","en":"Despite not studying much, he gets high scores on tests.","romaji":"Kare wa amari benkyou shinai wari ni wa, tesuto no tensuu ga takai desu."},{"jp":"この料理は見た目が悪いわりには、味は美味しいです。","en":"Even though this dish doesn't look good, it tastes delicious.","romaji":"Kono ryouri wa mitame ga warui wari ni wa, aji wa oishii desu."},{"jp":"彼女は若いわりには、とても落ち着いていますね。","en":"Considering she's young, she's very calm.","romaji":"Kanojo wa wakai wari ni wa, totemo ochitsuite imasu ne."},{"jp":"この部屋は狭いわりには、家賃が高いです。","en":"Despite being small, this room’s rent is high.","romaji":"Kono heya wa semai wari ni wa, yachin ga takai desu."}],"example":"彼はあまり勉強しないわりには、テストの点数が高いです。","exampleMeaning":"Despite not studying much, he gets high scores on tests."},{"pattern":"～んだって (〜n datte)","meaning":"Conveys information heard from someone else; 'I heard', 'They said'.","formation":"Verb-casual + んだって, い-Adjective + んだって, な-Adjective + なんだって, Noun + なんだって","examples":[{"jp":"彼は東京に行くんだって。","en":"I heard he's going to Tokyo.","romaji":"Kare wa Toukyou ni iku n datte."},{"jp":"この映画、面白いんだって。","en":"They said this movie is interesting.","romaji":"Kono eiga, omoshiroi n datte."},{"jp":"彼女は有名な歌手なんだって。","en":"I heard she's a famous singer.","romaji":"Kanojo wa yuumei na kashu na n datte."},{"jp":"あのレストラン、夜景がきれいなんだって。","en":"They said the night view at that restaurant is beautiful.","romaji":"Ano resutoran, yakei ga kirei na n datte."}],"example":"彼は東京に行くんだって。","exampleMeaning":"I heard he's going to Tokyo."},{"pattern":"～んだもん (〜nda mon)","meaning":"Used to convey a sense of justification; 'because', 'that's why', 'it's just that'.","formation":"Verb-casual + んだもん, い-Adjective + んだもん, な-Adjective + なんだもん, Noun + なんだもん","examples":[{"jp":"遅れたんだもん、ごめん。","en":"I was late, that's why I'm sorry.","romaji":"Okureta nda mon, gomen."},{"jp":"おいしいんだもん、もうちょっと食べたい。","en":"It's delicious, that's why I want to eat more.","romaji":"Oishii nda mon, mou chotto tabetai."},{"jp":"疲れているんだもん、早く寝たい。","en":"I'm tired, that's why I want to go to bed early.","romaji":"Tsukarete iru nda mon, hayaku netai."},{"jp":"彼は友達なんだもん、手伝わないわけにはいかない。","en":"He's my friend, that's why I can't not help him.","romaji":"Kare wa tomodachi nan da mon, tetsudawanai wake ni wa ikanai."}],"example":"遅れたんだもん、ごめん。","exampleMeaning":"I was late, that's why I'm sorry."},{"pattern":"～上げる (〜ageru)","meaning":"Indicates to finish doing something completely.","formation":"Verb-ますstem + 上げる","examples":[{"jp":"レポートを書き上げるまで、寝られません。","en":"I cannot sleep until I finish writing the report.","romaji":"Repooto o kakiageru made, neraremasen."},{"jp":"彼女は早速部屋の掃除を始め、一時間で掃除をやり上げた。","en":"She started cleaning the room right away and finished cleaning it in an hour.","romaji":"Kanojo wa sassoku heya no souji o hajime, ichijikan de souji o yariageta."},{"jp":"試験前夜、勉強をやり上げてから寝た。","en":"I went to bed after finishing studying on the night before the exam.","romaji":"Shiken zenya, benkyou o yariagete kara neta."},{"jp":"このプロジェクトをやり上げるためには、みんなの協力が必要です。","en":"To finish this project, everyone's cooperation is needed.","romaji":"Kono purojekuto o yariageru tame ni wa, minna no kyouryoku ga hitsuyou desu."}],"example":"レポートを書き上げるまで、寝られません。","exampleMeaning":"I cannot sleep until I finish writing the report."},{"pattern":"～切れない","meaning":"Expresses inability to completely finish or do something.","formation":"Verb-stem + 切れない","examples":[{"jp":"この本を一晩で読み切れない。","en":"I cannot finish reading this book in one night.","romaji":"Kono hon wo hitoban de yomikirenai."},{"jp":"彼は泣き切れないほど嬉しかった。","en":"He was so happy that he couldn't stop crying.","romaji":"Kare wa nakikirenai hodo ureshikatta."},{"jp":"この部屋を一日で掃除し切れない。","en":"I cannot finish cleaning this room in one day.","romaji":"Kono heya wo ichinichi de soujishikirenai."},{"jp":"彼女は話し切れないほどの悩みがある。","en":"She has so many worries that she can't finish talking about them.","romaji":"Kanojo wa hanashikirenai hodo no nayami ga aru."}],"example":"この本を一晩で読み切れない。","exampleMeaning":"I cannot finish reading this book in one night."},{"pattern":"必ずしも～とは限らない","meaning":"Not necessarily; not always.","formation":"必ずしも + Statement + とは限らない","examples":[{"jp":"高いものが必ずしも良いとは限らない。","en":"Expensive things are not necessarily better.","romaji":"Takai mono ga kanarazushimo yoi to wa kagiranai."},{"jp":"有名な人が必ずしも幸せとは限らない。","en":"Famous people are not necessarily happy.","romaji":"Yuumei na hito ga kanarazushimo shiawase to wa kagiranai."},{"jp":"外国語が話せる人が必ずしも英語が得意とは限らない。","en":"People who can speak a foreign language are not always good at English.","romaji":"Gaikokugo ga hanaseru hito ga kanarazushimo eigo ga tokui to wa kagiranai."},{"jp":"勉強時間が多い生徒が必ずしも試験で点数が高いとは限らない。","en":"Students who study a lot are not necessarily scoring high on exams.","romaji":"Benkyou jikan ga ooi seito ga kanarazushimo shiken de tensuu ga takai to wa kagiranai."}],"example":"高いものが必ずしも良いとは限らない。","exampleMeaning":"Expensive things are not necessarily better."},{"pattern":"～最中に","meaning":"In the middle of / while doing something.","formation":"Verb-て form + いる + 最中に, Noun + の + 最中に","examples":[{"jp":"昼寝をしている最中に電話が鳴った。","en":"The phone rang while I was taking a nap.","romaji":"Hirune o shiteiru saichuu ni denwa ga natta."},{"jp":"料理を作っている最中に火事が起こった。","en":"A fire broke out in the middle of cooking.","romaji":"Ryouri o tsukutteiru saichuu ni kaji ga okotta."},{"jp":"会議の最中に急な用事で出なければならなかった。","en":"I had to leave during the meeting because of an urgent matter.","romaji":"Kaigi no saichuu ni kyuu na youji de denakereba naranakatta."},{"jp":"試験の最中に地震が起こった。","en":"An earthquake occurred during the exam.","romaji":"Shiken no saichuu ni jishin ga okotta."}],"example":"昼寝をしている最中に電話が鳴った。","exampleMeaning":"The phone rang while I was taking a nap."},{"pattern":"決して～ない","meaning":"Express 'never', 'by no means', or 'not at all' when negating a statement.","formation":"決して + Verb (negative form)","examples":[{"jp":"彼は決して遅刻しない。","en":"He never arrives late.","romaji":"Kare wa kesshite chikoku shinai."},{"jp":"この秘密を決して誰にも言わないでください。","en":"Please never tell this secret to anyone.","romaji":"Kono himitsu o kesshite darenimo iwanai de kudasai."},{"jp":"決して諦めないで、最後までがんばりましょう。","en":"Never give up and keep trying until the end.","romaji":"Kesshite akiramenai de, saigo made ganbarimashou."},{"jp":"彼女は決して嘘をつかない人です。","en":"She is a person who never lies.","romaji":"Kanojo wa kesshite uso o tsukanai hito desu."}],"example":"彼は決して遅刻しない。","exampleMeaning":"He never arrives late."}]
